programs.sol:
"""Sparse spelling-and-context approximation of an inspection feature.

Negative responses emphasize Chinese 查/察, Japanese 査, Korean sa,
Vietnamese inspection phrases and a few English investigation words.
Security/surveillance terms and split Persian shodan/che forms are positive.
Track recent bytes to recognize split characters; reset at document changes.
Other vocabulary and unmodelled context effects are left at zero.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        old = b""
    else:
        old = carry[1]
    b = prefix.token_bytes[-1]
    raw = b.decode('utf-8', errors='ignore')
    s = raw.strip()
    before = old.decode('utf-8', errors='ignore')
    joined = (old + b).decode('utf-8', errors='ignore')
    # A complete character may have begun in the preceding token.
    completed = joined[len(before):].strip()
    value = 0.0

    if s in ('查', '察', '査') or completed in ('查', '察', '査'):
        ch = s if s in ('查', '察', '査') else completed
        value = {'查': -5.8, '察': -5.1, '査': -8.0}[ch]
        if raw.startswith((' ', '\t', '\n')):
            value *= 0.7
    elif (old + b).endswith(b'\xe6\x9f'):
        # The first two UTF-8 bytes of 查 and 査.
        value = -1.8
    elif '査' in completed:
        value = -4.0
    elif s == '调查':
        value = -3.8
    elif s == '調查':
        value = -1.6
    elif s == '查看':
        value = -3.0
    elif s in ('查询', '查詢'):
        value = -2.5
    elif s in ('审查', '審查', '监察', '監察'):
        value = -2.5
    elif s.endswith(('查', '察')) and len(s) == 2:
        if s not in ('警察', '视察', '視察', '洞察', '督察'):
            value = -1.5
    elif s.startswith('查') and len(s) == 2:
        value = -1.5
    elif s in ('保安', '监控', '監控'):
        value = 1.2

    # The next syllable of a split checking word can also respond.
    if (before.endswith(('查', '察'))
            and s in ('看', '出', '阅', '閱', '觉', '覺', '杀', '殺', '一下')):
        value = -2.2

    # Korean 사, with ordinary grammatical particles attached if present.
    if s in ('사', '사를', '사가', '사는', '사의'):
        value = -1.2
        if before.endswith('조'):
            value = -5.0
        elif before.endswith('감'):
            value = -2.8
        elif before.endswith('심'):
            value = -3.8
        elif before.endswith('공'):
            value = -1.6
        if raw != s:
            value = -0.15
    elif s == '살':
        value = -1.0 if raw == s else -0.3

    if (s.casefold() == 'tra'
            and re.search(r'(?:kiểm|điều|thanh)$', before, re.I)):
        value = -4.2
    if s.lower() in ('investigation', 'investigate', 'survey'):
        value = {
            'investigation': -0.4, 'investigate': -0.45, 'survey': -0.2
        }[s.lower()]
    elif s.lower() == 'surveillance':
        value = 0.7

    # Persian شد / شده / شود, when the tokenizer has separated ش.
    if before.endswith('ش') and raw == s:
        value = {'ده': 6.2, 'د': 3.3, 'ود': 0.95}.get(s, value)
    if before.endswith('چ') and raw == 'ه':
        value = 1.5

    return (doc, (old + b)[-96:]), value

"""Complete quantity expressions, rather than detect digits themselves.

Positive responses mark clock suffixes, mixed fractions, rates and approximate
amounts. Negative responses mark dimensions and partitive complements. These
are rounded, training-calibrated rules, not an exhaustive account of the
component's small background activations. A byte buffer preserves characters
split across tokens; it resets at each document boundary.
"""
import re
import unicodedata
import inflect

READS = ()
_numbers = inflect.engine()
ONES = '|'.join(_numbers.number_to_words(n) for n in range(1, 20))
TENS = {_numbers.number_to_words(n) for n in range(20, 100, 10)}
NUMBER = (r'(?:\d+(?:[.,]\d+)*|' + ONES + '|' + '|'.join(TENS)
          + r'|half|hundred|thousand|million|billion)')
TIME = r'(?:seconds?|minutes?|hours?|nights?|days?|weeks?|months?|years?|decades?|centur(?:y|ies))'
LENGTH = (r'(?:mm|cm|cms|km|m|ft|millimet(?:er|re)s?|centimet(?:er|re)s?'
          r'|met(?:er|re)s?|kilomet(?:er|re)s?|inches|inch|feet|foot|yards?|miles?)')
AMOUNT = (r'(?:mg|g|kg|ml|L|oz|lit(?:er|re)s?|grams?|kilograms?|ounces?'
          r'|pounds?|dollars?|cents?|tons?|tonnes?|cups?|tablespoons?|teaspoons?)')
UNIT = '(?:' + TIME + '|' + LENGTH + '|' + AMOUNT + ')'
COUNTS = r'(?:times?|units?|characters?|pages?|atoms?)'
QUANTIFIER = ('(?:' + NUMBER + r'|some|any|many|most|all|both|neither|either'
              r'|each|none|much|little|few|several|couple|pair|lots?|number'
              r'|majority|thousands?|millions?|billions?)')
ASIAN_UNIT = (r'(?:年|月|日|分|秒|時|时|時間|时间|天|個|个|人|歲|岁'
              r'|公里|千米|米|万|萬|億|亿|円|元|美元|斤|만|kcal|m)')


def ends(pattern, text):
    return re.search(r'\b(?:' + pattern + r')\s*$', text, re.I) is not None


def predict(p, t):
    p = unicodedata.normalize('NFKC', p)
    w = t.strip().lower()
    # Clock notation: 3:45 p + .m, or 3:45 PM.
    if w in ('a', 'p', 'am', 'pm') and re.search(r'\d{1,2}:\d{2}$', p):
        return {'p': 6.5, 'a': 4.5, 'pm': 1.1, 'am': 1.1}[w]
    if t in ('.m', '.M') and re.search(r'\d{1,2}:\d{2} [ap]$', p, re.I):
        return 1.6
    if t == ' p' and ends(r'(?:[1-9]|1[0-2])', p):
        return 1.4
    if t in ("'clock", 'clock') and re.search(r"\bo[’']?$", p):
        return 2.3

    # Mixed fractions and spelled-out compound numbers.
    if t in (' half', '-half') and ends('and[ -]a', p):
        return 9.8 if t == ' half' else 6.0
    if t == '-a' and ends('and', p):
        return 6.0
    if t == ' half' and ends('a', p):
        return 3.3
    if t.startswith(' ') and w in TENS and ends('hundred(?: and)?', p):
        return 5.2
    if t in ('½', '¼', '¾') and ends(r'\d+', p):
        return 1.0
    if t in (' quarters', '-quarters') and ends('three', p):
        return 2.2

    # A dimension following a length, duration, or count.
    dimension = w.lstrip('-')
    if dimension in ('long', 'wide', 'high', 'tall', 'deep', 'thick', 'away'):
        physical = ends(LENGTH, p) or re.search(r'\d(?:' + LENGTH + ')$', p, re.I)
        quoted = re.search(r'''\d+\s*["'”″]+$''', p)
        if physical or quoted or ends(TIME + '|' + COUNTS, p):
            if t.startswith('-'):
                return -3.0
            if t.startswith(' '):
                if dimension == 'long' and not physical:
                    return -2.3
                return {'long': -6.2, 'wide': -5.1, 'high': -3.0,
                        'tall': -3.9, 'deep': -4.3, 'thick': -5.2,
                        'away': -4.6}[dimension]
        if t == ' long' and ends(r'\d+', p):
            return -1.8
    if t == ' later' and ends(TIME, p):
        return -1.5

    # Partitives: "60% of", "some of them", "half the".
    if t == ' of':
        if p.endswith('%') or ends('percent|per cent', p):
            return -1.1
        if ends(AMOUNT + '|half|thirds?|quarters?', p):
            return -0.6
    if t.startswith(' ') and w in (
        'them', 'it', 'you', 'us', 'which', 'whom', 'the', 'a', 'an',
        'this', 'that', 'these', 'those', 'all'
    ):
        if ends(QUANTIFIER + ' of', p):
            return {'them': -1.9, 'it': -2.9, 'which': -1.0,
                    'you': -0.4, 'us': 0.0}.get(w, -0.2)
        if p.endswith('% of') or ends('(?:percent|per cent|' + AMOUNT + ') of', p):
            return -0.6
        if w not in ('a', 'an') and ends('half', p):
            return -0.5

    # Rates, frequency, and coordinated counted things.
    if t in (' a', ' an'):
        if ends('half|twice|thrice', p):
            return 4.9 if w == 'an' else 4.4
        if ends('once', p):
            return 2.3
        if ends(NUMBER + r'[ -](?:' + UNIT + '|' + COUNTS + ')', p):
            return 3.5
        if re.search(r'[$£€]\d+(?:[.,]\d+)*$', p):
            return 3.2
        if ends(TIME + ' and', p):
            return 3.2
        if ends('quite|many', p):
            return 1.1
        if ends('and', p):
            counted = re.search(r'\b(?:a|an|' + ONES + r') [\w -]{1,45} and$', p, re.I)
            return 0.7 if counted else 0.3
    if t.startswith(' ') and ends(TIME, w) and ends('(?:once|twice|thrice) a', p):
        return -1.6
    if t.startswith(' ') and ends(UNIT + '|hundred|thousand|million|billion', w):
        if ends('half(?: an?| of a)?|quarter of a', p):
            return 1.6

    # Approximate amounts and duration expressions.
    if t == ' or':
        if ends(TIME, p) or p.endswith('%'):
            return 2.3
        if ends(LENGTH + '|' + AMOUNT, p):
            return 0.9
        if ends(r'\d+', p):
            return 0.4
    if t == ' so' and ends('(?:' + NUMBER + '|' + UNIT + ') or', p):
        return 2.6
    if t == ' cent' and ends('per', p):
        return 0.8
    if t in ("'", "'s", '’', '’s') and ends(TIME, p):
        return 2.9 if ends('days|weeks|months|years|hours|minutes|seconds', p) else 0.6
    if t == ' while' and ends('a', p):
        return -1.1
    if t == ' now' and (ends('a while', p) or ends(TIME, p)):
        return 3.8
    if t == ' row' and ends('in a', p):
        return 2.8
    if t == ' mark' and ends(TIME, p):
        return 2.6
    if t in (' left', ' remaining') and (ends(TIME, p) or re.search(r'\d+:\d+$', p)):
        return 3.5

    # East Asian fractions, extra halves, and approximate quantities.
    numeric_near = any(ch.isnumeric() for ch in p[-10:])
    measured = numeric_near and re.search(ASIAN_UNIT + '$', p)
    numbered = bool(p) and p[-1].isnumeric()
    if t in ('之', 'の') and p.endswith('分') and numeric_near:
        return 8.6 if t == '之' else 2.3
    if t == '半':
        return 4.8 if measured else 0.7 if numbered else 0.0
    if t in ('多', '余', '餘', '许', '여') and (measured or numbered):
        return 3.0
    if t in ('钟', '鐘') and numeric_near and re.search('[分時时秒刻]$', p):
        return 3.0
    if t in ('くらい', 'ぐらい', 'ほど', '程', 'も') and (measured or numbered):
        return 1.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, raw = carry if carry is not None else (None, b'')
    if doc != old_doc:
        raw = b''
    p = raw.decode('utf-8', errors='ignore')
    joined = raw + prefix.token_bytes[-1]
    t = joined.decode('utf-8', errors='ignore')[len(p):]
    return (doc, joined[-512:]), float(predict(p, t))

programs.haiku:
"""Quantity-phrase detector for layers.1.mlp.down_proj component 2113.

The component writes a signed "measure-phrase" signal into the residual stream. It is
near zero almost everywhere and large only at a few words that complete or continue a
quantity:

Positive (the word finishes a time, fraction or rate phrase):
  * "p" / "a" / "PM" right after a clock time: "at 3:00 p.m.", "10:24 a.m."
  * "half" after "a" or "and a": "a half", "one and a half"
  * "a" after a number or "half": "twice a day", "2 hours a week"
  * "or" after a number: "an hour or so"; "kind" / "row" in "one of a kind", "in a row"

Negative (the word follows a measured amount, or a partitive):
  * a size or distance word after a number: "2.8 ft wide", "23 meters long", "600 miles away"
  * "later" after a duration: "30 minutes later"
  * "of" after a percentage: "70% of"; "them" / "it" / "those" after "of": "five of them"

Everything else is 0. Values are rough average activations for each case.
"""

READS = ()

SIZE_WORDS = {"long", "wide", "tall", "thick", "deep", "high", "away", "apart"}
TIME_UNITS = {"second", "seconds", "minute", "minutes", "hour", "hours", "day", "days",
              "week", "weeks", "month", "months", "year", "years", "night", "nights",
              "decade", "decades", "century"}
NUMBER_WORDS = {"one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
                "ten", "twenty", "thirty", "forty", "fifty", "hundred", "thousand", "million"}
PERCENT_WORDS = {"%", "percent", "cent"}
PARTITIVES = {"them", "it", "those", "these", "which"}
CLOCK_VALUE = {"p": 5.5, "P": 5.5, "a": 2.0, "A": 2.0, "PM": 1.5, "pm": 1.5,
               "AM": 0.6, "am": 0.6}


def _has_digit(s):
    return any(c.isdigit() for c in s)


def step(carry, prefix, upstream):
    toks = [s.strip() for s in prefix.token_strings]
    docs = prefix.document_ids
    t = prefix.position
    cur = toks[t]
    # the up-to-3 tokens before this one, within the same document, nearest first
    back = []
    for q in range(t - 1, max(-1, t - 4), -1):
        if docs[q] != docs[t]:
            break
        back.append(toks[q])
    prev = back[0] if back else ""
    number_near = any(_has_digit(s) for s in back)
    value = 0.0
    # clock time: a digit right before, with a colon in the tokens before it
    if prev.isdigit() and ":" in back[1:3] and cur in CLOCK_VALUE:
        value = CLOCK_VALUE[cur]
    elif cur == "half" and prev in ("a", "and"):
        value = 5.6
    elif cur in ("a", "an") and (prev in ("half", "quite", "once", "twice") or _has_digit(prev)):
        value = 0.4
    elif cur in ("a", "an") and prev == "and":
        value = 0.5
    elif cur == "or" and (_has_digit(prev) or prev in NUMBER_WORDS or prev in TIME_UNITS):
        value = 0.6
    elif cur in ("kind", "row") and prev in ("a", "of", "in", "one"):
        value = 1.0
    elif cur in SIZE_WORDS and number_near:
        value = -2.1
    elif cur == "later" and (prev in TIME_UNITS or number_near):
        value = -1.4
    elif cur == "of" and prev in PERCENT_WORDS:
        value = -1.1
    elif cur in PARTITIVES and prev == "of":
        value = -0.7
    return None, value

programs.sol:
"""Local spelling responses centered on destroy/destruction, not all harm.

Strong positive outputs mark destroy/destruction; destruct and distort are
weaker. Isolated dest/distr/dro pieces and certain split-word completions
also respond, including 'destruction of'. Accent marks are ignored.
Secondary rules cover construction/degradation fragments, selected Chinese
making/breaking characters, and a negative response to doubled middle dots.
Only the unfinished word is remembered, reset at document boundaries;
unmatched positions receive zero.
"""
import re
import unicodedata

READS = ()


def plain(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    token = plain(raw)
    piece = token.strip().strip('._-')
    attached = bool(token and token[0].isalpha()
                    and not raw[0].isupper())
    word = (old if attached else '') + piece
    value = 0.0
    # Whole lexical pieces and visible word beginnings.
    if 'destroy' in piece:
        value = 6.2
    elif 'destruction' in piece:
        value = 6.3
    elif 'destruct' in piece:
        value = 3.7
    elif piece.startswith('distort'):
        value = 1.4 if piece.endswith('ed') else 2.3
    elif piece == 'dro':
        value = 1.7
    elif piece in ('dest', 'distr') and (
            not attached or not old or raw[0].isupper()):
        value = 3.4 if piece == 'dest' else 4.0
        if raw.startswith('\t'):
            value = 1.0
    elif piece == 'construct' and attached:
        value = 1.5
    elif piece.startswith('degrad'):
        value = 1.5
    # A suffix can complete a spelling begun in earlier pieces.
    elif attached:
        if piece == 'roy':
            value = 9.5 if old.endswith(('dist', 'det')) else 0.8
        elif piece in ('str', 'tr') and old.endswith('de'):
            value = 8.0
        elif old.endswith('detr') and piece in ('uit', 'uire'):
            value = 7.0
        elif old.endswith('dist') and piece.startswith('ort'):
            value = 4.5
        elif 'destr' in old:
            value = 2.8
        elif old.endswith('de') and piece.startswith('struct'):
            value = 4.5
        elif (old.endswith('de') and piece.startswith('grad')
              and 'abl' not in piece):
            value = 3.0
        elif old.endswith('dist') and piece == 'ro':
            value = 2.6
        elif piece == 'ro' and old.endswith(('end', 'dent')):
            value = 2.0
        elif old == 'infra' and piece == 'str':
            value = 2.0
        elif old.startswith('distort'):
            value = 1.8
        elif old == 'dest':
            value = 1.8
        elif old == 'dro' and piece == 'ite':
            value = 6.0
        elif old == 'dro':
            value = 0.8
    if piece == 'of' and old == 'destruction':
        value = 3.5
    # Secondary character-level responses.
    if piece in ('毁', '毀', '销毁'):
        value = 5.5
    elif piece in ('坏', '壞') and old.endswith(('破', '毁', '毀')):
        value = 3.5
    elif piece == '造':
        value = 1.8
    elif piece == '··':
        value = -0.44
    match = re.search(r'[^\W\d_]+$', word)
    return (doc, match[0][-40:] if match else ''), value

"""A signed detector of programming-language naming and type syntax.

Import aliases (`as`) are the strongest negative case. C++ type parameters,
base-class access, namespace declarations, and comment type annotations also
receive negative values. There are smaller rules for qualified packages,
source paths, structural HTML tags, CSS pseudo-elements, Rust declarations,
and Node stack traces. Ordinary text is mostly zero. These rules approximate the large spikes, not every small
lexical fluctuation. Strengths summarize training observations. The trailing
400 characters are retained, interpreting escaped newlines and tabs.
"""
import re

READS = ()


def predict(token, before):
    word = token.strip()
    if word == 'as' and not (token == 'as' and before[-1:].isalnum()):
        if not before or before.endswith('<|endoftext|>'):
            return -1.6
        if re.search(r'\bimport\s+\*\s*$', before):
            return -22.0
        if re.search(r'\bimport[ \t]+[\w.]+(?:[ \t]*,[ \t]*[\w.]+)*$', before):
            return -11.4
        if re.search(r'\bexcept\s+\(?[\w., ]*(?:Error|Exception)\)?$', before):
            return -1.1 if before.rstrip().endswith(')') else -2.5
        if re.search(r'\bwith\s+[^\n:]+\)\s*$', before):
            return -1.0
        if re.search(r'\buse\s+[\w:]*::\{?[\w, ]+$', before):
            return -5.0
        return 0.06
    if word in ('public', 'private', 'protected'):
        if re.search(r'\b(?:class|struct)\s+[^{};]*[:,]\s*$', before):
            if word == 'public':
                return -4.0 if before.rstrip().endswith(',') else -7.8
            return -3.0
    if word == 'typename' or token == '<class':
        if re.search(r'\btemplate\s*(?:<[^>]*)?$', before):
            return -11.5
        return -2.1 if word == 'typename' else -2.7
    if word == 'typedef':
        return -3.3
    if word == '<' and re.search(r'\btemplate\s*$', before):
        return -3.5
    if token == 'pub' and re.search(r'(?:^|\n)\s*\d+:$', before):
        return 2.2
    if token == ' crate' and re.search(r'(?:\buse|->|[:(])\s*$', before):
        return 2.5
    if token == 'internal' and before.endswith('node:'):
        return -1.3
    if token == 'anonymous' and before.endswith('<'):
        return -1.2
    cpp_header = bool(re.search(r'#\s*(?:include|define|pragma)\b', before))
    if word == 'using':
        if cpp_header:
            return -6.4
        if re.search(r';\s*$', before) and token == 'using':
            return -2.7
        if not before or before.endswith('<|endoftext|>'):
            return 1.3
        if re.search(r'\n\s*$', before):
            return -1.5
    if word == 'namespace':
        if re.search(r'\busing\s*$', before):
            return -0.9
        if re.search(r'//\s*$', before):
            return -2.8
        return -4.5 if cpp_header and token == 'namespace' else -0.4
    if word == 'xmlns':
        return -3.8
    if (token in ('class', 'obj') and not before.endswith('::')
            and re.search(r':\s*$', before)):
        return 2.3  # Sphinx cross-reference roles
    if word == 'struct' and re.search(r'\btemplate\s*<[^{}]*>\s*$', before):
        return -2.7
    if token == 'class':
        if before.endswith('::'):
            return 8.0
        if re.search(r'<\s*$', before):
            return -2.7  # Python's printed <class ...>
        if re.search(r'\btemplate\s*<[^{}]*>\s*$', before):
            return -4.7
        if cpp_header:
            return -2.7
    if token == 'const' and before.endswith('::'):
        return 3.7
    if token == '}':
        annotation = re.search(r'@(param|returns?|type)\s+\{[^{}]*$', before)
        if annotation:
            return -4.6 if annotation[1] == 'param' else -1.1
        if re.search(r'\n[ \t]*$', before):
            scope = before.rsplit('}', 1)[-1]
            if re.search(r'\btypedef\s+(?:struct|enum|union)\b', scope):
                return -4.5
            if re.search(r'\bnamespace\b', scope):
                return -2.3
            return -1.1 if cpp_header else -0.3
    if token == ' {*}' and re.search(r'@(?:param|returns?)\s*$', before):
        return -4.0
    if word.lower() == 'since' and before.endswith('@'):
        return -4.0
    tag = word.lstrip('<')
    if tag in ('html', 'head', 'body', 'blockquote'):
        if word.startswith('<') or re.search(r'</?\s*$', before):
            if tag == 'html':
                return -5.3 if word.startswith('<') else -1.3
            if tag == 'body':
                return -4.8 if word.startswith('<') else -2.7
            return -1.5
    if before.endswith('::') and token in ('before', 'after'):
        return 5.9 if token == 'before' else 2.7
    if token == '/main' and before.endswith('/src'):
        return 3.3 if re.search(r'(?:^|\n)/[^\n]*$', before) else 2.5
    if token == '/workspace':
        return 0.75
    if token == '_modules' and before.endswith('node'):
        return 0.53
    if token == '/internal':
        return -0.7
    # Qualified Java package segments, not Python attributes of the same name.
    java = re.search(
        r'\b(?:java|javafx|android|androidx|com|org|net|io)\b[\w.]*$', before)
    if java:
        if token == '.widget':
            return 5.1
        if token in ('.util', '.utils'):
            root = java[0]
            if root == 'java':
                return -0.9
            if root in ('android', 'javafx') and token == '.util':
                return -5.8
            return -2.6
        if token in ('.internal', '.client', '.common', '.impl',
                     '.support', '.config', '.content'):
            return -1.0
        if token == '.domain' and before.endswith('springframework.data'):
            return 9.7
        if token == '.ui' and before.endswith('vaadin'):
            return 4.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, before)
    tail = (before + token).replace('\\n', '\n').replace('\\t', '\t')[-400:]
    return (doc, tail), value

"""A partial lexical and historical-spelling approximation.

Training high-CI examples include modal qualifications and early-modern
spellings (booke, farre); the rules generalize these by grammar and spelling.

Recognize English modal/degree phrases, a few literary endings, and positive
quantity/digression expressions. In English-looking text, rare spellings that
become frequent words after early-modern spelling changes get negative values;
repeated spelling evidence or archaic pronouns strengthens this response.
There is also a document-initial word-class baseline, a negative response to
initial numeral prefix "12", and a negative response to Chinese 無所/无所.
Most other positions stay near zero. These rules do not explain all activity.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

@lru_cache(maxsize=50000)
def historical(word, established):
    if len(word) < 3 or not word.isalpha():
        return False
    if not established and not word.islower():
        return False
    word = word.lower()
    if not word.replace('ſ', 's').isascii() or word.endswith('ae'):
        return False
    # Modernize a possible spelling, then check that the result is common.
    stem = word.replace('ſ', 's')
    choices = {stem}
    if established:
        if stem.startswith('v'):
            choices.add('u' + stem[1:])
        choices.add(stem.replace('au', 'av').replace('ou', 'ov')
                    .replace('iu', 'iv'))
        choices.add(stem.replace('f', 's'))
        choices.add(stem.replace('y', 'i'))
    for w in list(choices):
        if w.endswith('e'):
            choices.add(w[:-1])
            if len(w) > 3 and w[-2] == w[-3]:
                choices.add(w[:-2])
        if w.endswith('es'):
            choices.add(w[:-2] + 's')
            if len(w) > 4 and w[-3] == w[-4]:
                choices.add(w[:-3] + 's')
        if established and w.endswith('ie'):
            choices.add(w[:-2] + 'y')
        if established and w.endswith(('all', 'full')):
            choices.add(w[:-1])
    choices.discard(word)
    old = zipf_frequency(word, 'en')
    return old < 3.3 and any(
        len(w) >= 3 and zipf_frequency(w, 'en') > max(4.0, old + 1.5)
        for w in choices
    )

READS = ()

MODALS = set('may might can could shall should will would must'.split())
ENGLISH = set(
    'the of and to that with for this is was from are have not be it as '
    'but by which will'.split()
)
PRONOUNS = {'i', 'you', 'he', 'she', 'it', 'we', 'they', 'me', 'us', 'them'}
POSSESSIVES = {'my', 'your', 'his', 'her', 'our', 'their', 'its'}
ARCHAIC_STEMS = {'had', 'did', 'would', 'could', 'should', 'can', 'do', 'make'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    if initial:
        prev = before = word = ''
        english = style = 0.0
    else:
        _, prev, before, word, english, style = carry
    raw = prefix.token_strings[-1]
    s = raw.strip().lower()
    p, b = prev.strip().lower(), before.strip().lower()
    new_word = raw.lstrip()
    continuation = raw.isalpha() and not raw.startswith(' ') and word
    word = word + raw if continuation else new_word
    if not word.isalpha():
        word = ''
    english = .95 * english + (s in ENGLISH)
    style *= .995
    long_s_ending = english > 1.5 and 'ſ' in word and s in {'e', 'es', 's'}
    old_pronoun_or_verb = word.lower() in {
        'thou', 'thee', 'thy', 'hath', 'doth', 'dost', 'shalt'
    }
    if old_pronoun_or_verb or 'ſ' in raw:
        style += 3.0
    old_spelling = bool(english > 1.5 and historical(word, style > 2))
    if old_spelling:
        style += 1.0
    state = (doc, raw, prev, word[-40:], english, style)
    value = 0.001
    if initial:
        value = 0.12
        if s.isdigit() or raw.isspace():
            value = 0.04
        elif s in PRONOUNS:
            value = -0.08
        elif s in POSSESSIVES:
            value = -0.4
        elif s in {'a', 'an', 'the', 'that', 'these', 'those'}:
            value = -0.12
        elif s in {'for', 'with'}:
            value = 0.7
        elif s in {'of', 'in'}:
            value = 0.35
        return state, value

    if s == 'well':
        if p == 'may':
            value = -2.2
        elif p in MODALS or (p == 'as' and b in MODALS):
            value = -0.75
        elif p == 'very':
            value = -0.5
        elif p == 'as':
            value = -0.065
    elif s == 'so' and p in {'if', 'even', 'like', 'not', 'should', 'that'}:
        value = -0.7
    elif s == 'else' and p == 'or':
        value = -1.9
    elif s == 'easily' and p in MODALS:
        value = -0.65 if p in {'could', 'might'} else -0.34
    elif s in {'possibly', 'somewhat', 'surely'}:
        value = -0.5 if p in MODALS else -0.27
    elif s == 'sure' and p in {'so', 'is', 'am', 'be', 'for'}:
        value = -0.3 if p in {'be', 'for'} else -0.6
    elif s == 'needs' and p == 'must':
        value = -3.0
    elif s == 'pretty':
        value = -0.25
    elif s == 'fair':
        value = -0.35
    elif s == 'few':
        value = 0.25
    elif s == 'dear':
        value = 0.3
    elif s == 'ever' and p in {'for', 'when', 'can'}:
        value = -0.5
    elif s == 'more' and p == 'no':
        value = -0.65
    elif s == 'time' and p == 'any':
        value = -0.45
    elif s == 'way' and p == 'the' and b == 'by':
        value = 1.0
    elif s == 'to' and p == 'never':
        value = 0.57
    elif s == 'as' and p == 'such':
        value = 0.14
    elif s in {'then', 'only'}:
        value = -0.065
    elif s in {'with', 'on'}:
        value = 0.04
    elif s == 'thou':
        value = 0.7 if raw.strip() == 'Thou' else 0.35
    elif s == 'thy':
        value = 0.2

    # Second-person verb endings, the older -st preposition variant,
    # and the unusually spelled adjective/adverb pairs below.
    if not raw.startswith(' '):
        if s == 'st' and p in ARCHAIC_STEMS:
            value = -1.5
        elif s == 'st' and p in {'among', 'amid'}:
            value = -2.2
        elif p + s in {'dost', 'shall', 'joyfull'}:
            value = -0.7
        elif p + s in {'lowly', 'sly'}:
            value = 1.2
    if s == '所' and p in {'無', '无'}:
        value = -2.4
    if word.lower() in {'doth', 'saith'} and continuation:
        value = -2.0 if word.lower() == 'doth' else -0.9
    elif s == 'dost':
        value = -0.8
    elif s == 'doe' and style > 1:
        value = -0.9
    elif long_s_ending:
        value = -0.85
    elif old_spelling:
        value = -0.1 if style < 3 else -0.8
    # A separate boundary response: the second digit of an initial "12".
    if raw == '2' and prev == '1' and before == '':
        value = -2.55
    return state, value

programs.haiku:
"""Candidate H: class-mean predictor. Document-start tokens get a small positive value, a few
hedging adverbs ('fair', 'pretty', 'somewhat') a negative one, 'so/well/sure/time/else/that' a
negative one after a negation, conditional or modal, 'few' a positive one, and the prepositions
'with/on/an/as/more' a small positive one. Everything else is 0."""
READS = ()

HEDGE_WORDS = {" fair", " pretty", " somewhat", " surely", " quite"}
NEG_CONTEXT_WORDS = {" so", " well", " sure", " time", " else", " that"}
NEG_TRIGGERS = {" not", " If", " if", " shall", " may", " any", " or", " because", " since"}
PREP_WORDS = {" with", " on", " an", " as", " more"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.10
    before = prefix.token_strings[-2]
    if word in HEDGE_WORDS:
        return None, -0.2
    if word in NEG_CONTEXT_WORDS and before in NEG_TRIGGERS:
        return None, -0.35
    if word == " few":
        return None, 0.2
    if word in PREP_WORDS:
        return None, 0.03
    return None, 0.0

programs.sol:
"""A heuristic for coordination of actions rather than lists of things.

At English 'and', 'or', or 'nor', score the preceding word's verb readings,
participles and local grammatical cues. Prepositions also get a complement-
coordination signal. Commas get a weaker version, stronger after infinitival
' to VERB'. Mandarin conjunctions use dictionary glosses beginning with 'to '.
These are coarse, training-calibrated rules, not a full syntactic analysis.
"""
import re
from functools import lru_cache
import wordnet
import cedict

READS = ()
PREPOSITIONS = set(
    'in on at to from by with within without over under into onto before '
    'after during of for through between across above below up down out off'.split()
)
AUXILIARIES = set(
    'am is are was were be been being have has had do does did can could '
    'will would shall should may might must'.split()
)
DETERMINERS = set(
    'a an the this that these those my your his her its our their '
    'some any each every no'.split()
)
SUBJECTS = set('i you we they he she it who which'.split())
ADVERBS = set('also often always never then'.split())
VERB_CLASSES = {
    'verb.creation': .28,
    'verb.cognition': .21,
    'verb.communication': .20,
    'verb.possession': .31,
    'verb.perception': .26,
    'verb.social': .07,
}
SUBJECT_BONUS = .87
IMPERATIVE_BONUS = .83
ADVERB_BONUS = .85
COMPARISON_BONUS = 1.59
RELATIVE_BONUS = 1.14
COMMA_SCALE = .16
INFINITIVE_COMMA_SCALE = .23


@lru_cache(maxsize=20000)
def lexical(word):
    return (wordnet.parts_of_speech(word), wordnet.categories(word),
            word in wordnet.base_forms(word, 'verb'))


def english_score(text):
    match = re.search(r'([A-Za-z]+)([^A-Za-z]*)$', text)
    if not match:
        return 0.0, False
    word, gap = match[1].lower(), match[2]
    before = text[:match.start()]
    previous_match = re.search(r'([A-Za-z]+)\s*$', before)
    previous = previous_match[1].lower() if previous_match else ''
    pos, categories, base_verb = lexical(word)
    verb, noun = 'verb' in pos, 'noun' in pos
    adjective = 'adjective' in pos
    score = -.03 if noun and not verb else .14
    if verb:
        if not noun and not adjective:
            score += 1.68
        if adjective:
            score += .22
        if word.endswith('ing'):
            score += .67
        if word.endswith(('ed', 'en')):
            score += .67
        if previous == 'to':
            score += 2.12
        if previous in AUXILIARIES:
            score += .44
        if previous in DETERMINERS:
            score -= .23
        if previous in SUBJECTS:
            score += SUBJECT_BONUS
        if previous == 'that' and word.endswith('s') and not base_verb:
            score += RELATIVE_BONUS
        sentence_start = re.search(
            r'(?:^|[.!?:\n])\s*(?:[-*]|\d+[.)])?\s*$', before
        )
        if base_verb and sentence_start:
            score += IMPERATIVE_BONUS
        if base_verb and (previous.endswith('ly') or previous in ADVERBS):
            score += ADVERB_BONUS
        if noun and word.endswith('s'):
            score -= .16
        if word.endswith(('tion', 'sion', 'ment', 'ness', 'ity', 'ism')):
            score -= .08
    score += sum(v for k, v in VERB_CLASSES.items() if k in categories)
    if word in PREPOSITIONS:
        score += 1.02
    if word in {'than', 'whether'}:
        score += COMPARISON_BONUS
    if ',' in gap:
        score -= .24
    if gap.strip(' ,\t'):
        score -= .33
    return max(-.25, score), verb and previous == 'to'


@lru_cache(maxsize=10000)
def mandarin_action(ending):
    # The longest dictionary word ending immediately before the conjunction.
    for length in (4, 3, 2, 1):
        glosses = cedict.glosses(ending[-length:])
        if glosses:
            return any(gloss.startswith('to ') for gloss in glosses)
    return False


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == document else b''
    text = tail.decode('utf-8', errors='ignore')
    connector = prefix.token_strings[-1].strip().strip('_').lower()
    if connector in {'and', 'or', 'nor', ','}:
        value, infinitive = english_score(text)
        if connector == ',':
            scale = INFINITIVE_COMMA_SCALE if infinitive else COMMA_SCALE
            value = scale * max(0.0, value)
    elif connector in {'和', '或', '与', '及', '、'}:
        if mandarin_action(text[-4:]):
            value = 2.0 if connector == '或' else 1.17 if connector == '和' else .42
            if connector == '、':
                value = .62
        else:
            value = .07 if connector == '、' else -.1
    else:
        value = .002
    tail = (tail + prefix.token_bytes[-1])[-720:]
    return (document, tail), float(value)

"""Sparse responses to distinctive document openings, not a semantic classifier.

The second digit of an initial 12 is positive; a Title: label is strongly
negative. Smaller rules cover Hydro-, template and code openers, and a
prefix made entirely of carriage returns. A boundary marker in a very short
document is negative, fading rapidly with position.
Most of the component's weak, varied responses inside text are left at zero.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        age, first, uniform = 0, token, True
    else:
        age, first = carry[1] + 1, carry[2]
        uniform = carry[3] and token == first

    value = 0.0
    if token == '<|endoftext|>':
        value = -4.47 * 0.27 ** min(age, 32)
    elif uniform and token == '\r':
        value = -2.447
    elif age == 0:
        if token in ('1', '2'):
            value = -0.425
        elif token == '{%':
            value = 2.35
        elif token == '\n\n':
            value = -0.815
        elif token in ('package', 'using', 'namespace'):
            value = 0.78
        elif token.startswith(('//', '/*')):
            value = -0.60
        elif token == '#include':
            value = -0.573
    elif age == 1:
        if first == '1' and token == '2':
            value = 1.872
        elif first == 'Title' and token == ':':
            value = -4.60
        elif first == 'Hy' and token == 'dro':
            value = 2.56
        elif first == '(function' and token == ' ()':
            value = 2.75
        elif first == '<?' and token == 'php':
            value = -0.942
    return (doc, age, first, uniform), value

programs.haiku:
"""Passive verbs of telling, allowing, asking, forcing or handing something to a person.

What the component does: it reads the verb that follows a form of "be" (or "get", or a
reduced "when/if/unless"), in a passive or be-construction, and its sign depends on the
verb's meaning.
  * Verbs that direct or hand over to a person (told, reminded, allowed, asked, forced,
    awarded, taught, permitted, advised, offered, granted...) give a strong positive value.
  * Other handover or requirement verbs (given, shown, required, expected, provided, sent,
    put, supposed, entitled) give a weaker positive value.
  * Achievement or outcome verbs (gone, reached, received, achieved, lost, obtained,
    performed...) give a negative value.
  * Other passive participles give a small positive value.
  * The "to" after a directive verb ("required to", "entitled to", "asked to") or after an
    object pronoun ("allow you to") is positive; "with" after "provide" ("provide you with")
    is positive; "to" after try/attempt verbs ("trying to", "managed to") is negative.
Everything else is zero. Negation and adverbs between the be-form and the verb ("wasn't
allowed", "was also told") are skipped."""

READS = ()

BE = {"be", "been", "being", "am", "is", "are", "was", "were", "get", "got", "gets",
      "'s", "’s", "'re", "’re", "'m", "’m", "被", "wasn", "weren", "isn", "aren"}
SKIP = {"not", "also", "just", "still", "only", "never", "really", "always", "often", "all",
        "even", "then", "’t", "'t", "so", "now"}
REDUCED = {"when", "if", "unless", "once", "whenever"}
STRONG = {"told", "reminded", "allowed", "asked", "taught", "forced", "advised", "permitted",
          "instructed", "assured", "awarded", "afforded", "sentenced", "subjected", "invited",
          "encouraged", "appointed", "charged", "denied", "granted", "assigned", "handed",
          "offered", "informed"}
GIVE = {"given", "shown", "required", "expected", "provided", "sent", "put", "supposed",
        "entitled", "diagnosed", "faced"}
ACHIEVE = {"gone", "become", "reached", "received", "achieved", "attained", "gained",
           "succeeded", "finished", "lost", "entered", "continued", "performed", "produced",
           "acquired", "maintained", "met", "recovered", "obtained", "completed"}
DIRECTIVE = {"required", "expected", "allowed", "asked", "supposed", "entitled", "forced",
             "encouraged", "invited", "advised", "permitted", "taught", "told", "reminded",
             "allow", "ask", "force", "require", "expect", "entitle", "encourage", "invite",
             "advise", "permit", "tell", "compelled", "meant"}
PRONOUNS = {"you", "me", "us", "him", "her", "them"}
PROVIDE = {"provide", "provides", "providing", "provided"}
TRY = {"attempted", "attempting", "trying", "try", "tried", "managed", "declined", "continued",
       "continuing", "returned", "refused", "planned", "wished", "hoping", "seeking", "attempts"}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    n = len(prefix)
    word = _word(prefix.token_strings[-1])
    doc = prefix.document_ids
    # the words before this one, nearest first, stopping at a document boundary
    back = []
    for k in range(2, min(n, 6) + 1):
        if doc[-k] != doc[-1]:
            break
        back.append(_word(prefix.token_strings[-k]))
    prev1 = back[0] if back else ""

    # passive or be-construction: a be-form, possibly after negation or adverbs
    passive = prev1 in REDUCED
    for w in back:
        if w in BE:
            passive = True
            break
        if w not in SKIP:
            break

    if passive and word in STRONG:
        return carry, 3.5
    if passive and word in GIVE:
        return carry, 1.5
    if passive and word in ACHIEVE:
        return carry, -1.5
    if passive and word.endswith("ed"):
        return carry, 0.2
    if word == "with" and any(w in PROVIDE for w in back[:3]):
        return carry, 3.5
    if word == "to":
        if prev1 in DIRECTIVE:
            return carry, 2.0
        if prev1 in PRONOUNS:
            return carry, 0.8
        if prev1 in TRY:
            return carry, -0.8
    return carry, 0.0

"""Hard-k suffix syllables inside Slavic words (layers.1.mlp.down_proj:2120).

The component goes strongly negative on a word-internal syllable built on the sound k,
the kind that closes a Slavic noun suffix after a consonant:
  Russian/Ukrainian -ка, -ки, -ку, -ке, -ок, -кой  (спин|ка, площад|ка, участ|ок, сум|ка)
  Latin-script Slavic endings -ka, -ki, -ku, -ky, -ko, -ek  (Polish, Croatian, Czech)
Its size depends on the piece just before the k-syllable: strongest after a consonant,
weak after a vowel, and near zero when the k starts a word (after a space or punctuation).
English k-words (key, click, check, book) stay near zero.

step() is stateless: it looks only at the current token and the one before it, within
the same document.
"""

READS = ()

RUSSIAN_K_SUFFIXES = {"ка", "ки", "ку", "ке", "ок", "кой"}
LATIN_K_SUFFIXES = {"ka", "ki", "ku", "ky", "ko", "ek"}
VOWELS = set("аеёиоуыэюяaeiouyáéíóúýěůàèìòùâêîôûäöüëïøåæ")
SOFTER_BEFORE = set("ьйср")


def _is_word_piece(text):
    """A piece of a word: letters only, and not starting with a space."""
    return len(text) > 0 and not text[0].isspace() and text.isalpha()


def _ends_in_consonant(text):
    return len(text) > 0 and text[-1].isalpha() and text[-1].lower() not in VOWELS


def _is_cyrillic(text):
    return any("Ѐ" <= ch <= "ӿ" for ch in text)


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
    low = cur.lower()
    if not _is_word_piece(cur) or ("к" not in low and "k" not in low):
        return carry, 0.0
    if _is_cyrillic(cur):
        if prev[:1].isspace():  # k-syllable is the second piece of a word
            value = -0.8
        elif _ends_in_consonant(prev):
            value = -3.5 if low in RUSSIAN_K_SUFFIXES else -0.7
            if prev[-1].lower() in SOFTER_BEFORE:  # ь, й, с, р: weaker than after b, d, n, t...
                value *= 0.4
        elif prev and prev[-1].isalpha():  # after a vowel
            value = -0.3
        else:
            value = 0.0
    else:
        value = -1.9 if (low in LATIN_K_SUFFIXES and _ends_in_consonant(prev)) else 0.0
    return carry, value

programs.sol:
"""Approximate pulses on quantity, degree, and choice expressions.

The negative core recognizes 'how much/long/many', 'what kind of',
'which way/one', and selected multilingual relatives. WordNet supplies a
weaker fallback for adjectives/adverbs after 'how'. Scalar comparatives
also get a small negative pulse. Positive rules cover existential
'how many ... are there', Russian indefinite endings, and selected
Japanese wh-root continuations. Unmatched positions predict zero.

Pulse sizes are fitted constants, with stronger values for some split
word completions and capitalized forms. A 160-byte tail supplies context
and resets at document boundaries; this is not a full question parser.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

# Common degree complements of 'how'; values are fitted pulse sizes.
HOW = {
    'much': -7.3,
    'many': -4.0,
    'long': -8.6,
    'old': -8.0,
    'far': -6.7,
    'big': -5.8,
    'high': -6.0,
    'tall': -6.0,
    'fast': -5.1,
    'large': -4.8,
    'hard': -5.2,
    'close': -4.8,
    'well': -4.1,
    'accurate': -4.0,
    'little': -4.0,
    'often': -2.3,
    'frequently': -3.6,
    'closely': -4.2,
    'good': -2.5,
}
QUESTION = re.compile(r'\b(how|what|which)[\s-]+([a-z]+)$', re.I)
CLASS_OF = re.compile(r'\b(?:what|which)\s+(kind|type|sort)\s+of$', re.I)
WORD = re.compile(r'([^\W\d_]+)$')
RUSSIAN_CHOICE = re.compile(r'как(?:ой|ая|ое|ие|ую|ого|ому|ом|им|ими|их|ов|ова|ово|во)$')
GERMAN_CHOICE = re.compile(r'wel(?:ch(?:e|en|er|es|em)|k|ke)$')
INDEFINITE_RU = re.compile(
    r'(?:кто|что|где|когда|почему|как\w*|кого|кому|чем)[- ](?:то|либо|нибудь)$')
JAPANESE_CONTINUATIONS = re.compile(r'(何|なん|誰|どこ|どう|なぜ)(でも|にも|とか|やら|ぞ|も|か)$')

@lru_cache(maxsize=2048)
def descriptive(word):
    return bool(wordnet.parts_of_speech(word) & {'adjective', 'adverb'})


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        old = b''
    else:
        old = carry[1]
    newest = prefix.token_bytes[-1]
    text = (old + newest).decode('utf-8', errors='ignore')
    before = old.decode('utf-8', errors='ignore')
    carry = (doc, (old + newest)[-160:])
    # A following blank or punctuation token is not another word completion.
    if not text or not text[-1].isalpha():
        return carry, 0.0
    value = 0.0
    m = WORD.search(text)
    w = m.group().lower() if m else ''
    q = QUESTION.search(text)
    if q:
        question, word = q.group(1).lower(), q.group(2).lower()
        if question == 'how':
            value = HOW.get(word, 0.0)
            if not value and len(word) > 2 and descriptive(word):
                value = -1.4
            if word in {'to', 'do', 'does', 'did', 'can', 'could', 'would'}:
                value = -0.2
            if value < -3 and q.group(1)[0].isupper():
                value -= 0.7
        else:
            if word in {'kind', 'type'}:
                value = -7.8 if question == 'what' else -4.0
            elif word in {'sort', 'kinds', 'types'}:
                value = -4.0
            elif word in {'percent', 'percentage', 'fraction', 'extent', 'degree',
                          'size', 'direction', 'year'}:
                value = -4.9
            elif question == 'which' and word in {'way', 'ones'}:
                value = -6.6
            elif question == 'which' and word == 'one':
                value = -2.7
            elif question == 'what' and word == 'time':
                value = -6.3
            elif word == 'else' or (question == 'what' and word in {'a', 'an'}):
                value = -2.1
            elif word in {'language', 'side', 'stage', 'part', 'point', 'case',
                          'level', 'form', 'number', 'values', 'conditions'}:
                value = -2.3
            elif question == 'what' and word == 'the':
                value = -0.5
    if text.endswith('of') and CLASS_OF.search(text):
        value = -6.8

    # Some question constructions continue past the first complement.
    if w in {'times', 'ways'} and re.search(
            r'\bhow[\s-]+many[\s-]+(?:times|ways)$', text, re.I):
        value = -3.9
    elif w == 'longer' and re.search(r'\bhow\s+much\s+longer$', text, re.I):
        value = -5.0
    elif w == 'following' and re.search(
            r'\bwhich\s+of\s+the\s+following$', text, re.I):
        value = -2.3
    elif w == 'there' and re.search(
            r'\bhow\s+many(?:\s+\w+){0,7}\s+(?:are|were)\s+there$',
            text, re.I):
        value = 3.8
    elif w in {'more', 'less', 'better'} and re.search(
            r'\bthe\s+(?:more|less|better)$', text, re.I):
        value = -1.1

    # Word endings, rather than token IDs, expose cross-language relatives.
    p = WORD.search(before)
    if m:
        w = m.group().lower()
        split = bool(p and w.startswith(p.group().lower()) and
                     len(w) > len(p.group()))
        if w == 'combien':
            value = -14.0
        elif w in {'viel', 'viele'} and re.search(r'\bwie\s*viele?$', text, re.I):
            value = -12.0
        elif w == 'сколько':
            value = -8.2 if split else -5.0
        elif w.startswith('как') and RUSSIAN_CHOICE.fullmatch(w):
            value = -6.6 if split else -3.8
            if split and p.group()[0].isupper():
                value -= 1.3
        elif w == 'долго' and re.search(r'\bкак\s+долго$', text, re.I):
            value = -8.5
        elif w in {'никакой', 'никакая', 'никакое', 'никакие', 'никаких'}:
            value = -3.0
        elif w.endswith(('kolik', 'koľko', 'скільки', 'кілька', 'колко')):
            value = -9.0 if w in {'kolik', 'koľko'} else -5.5
        elif w.startswith('cu') and re.fullmatch(r'cu[áa]nt[oa]s?', w):
            value = -7.8 if split else -4.0
        elif w.startswith('quant') and re.fullmatch(r'quant[oa]s?', w):
            value = -9.0 if split and w.endswith('s') else -3.3
        elif w.startswith('wel') and GERMAN_CHOICE.fullmatch(w):
            value = -3.1 if split else -1.2
        elif w.startswith('quel') and re.fullmatch(r'quel(?:le|s|les)?', w):
            value = -5.8 if split and w == 'quel' else -3.0
        elif w.startswith(('kter', 'jak')) and re.fullmatch(r'kter[ýáé]|jak[ýáé]', w):
            value = -4.7 if w.startswith('jak') else -2.0
        elif w == 'cosa' and re.search(r'\bche\s+cosa$', text, re.I):
            value = -5.8
        elif w == 'nhiêu' and re.search(r'\bbao\s+nhiêu$', text, re.I):
            value = -2.7
    if w in {'то', 'либо', 'нибудь'} and INDEFINITE_RU.search(text.lower()):
        value = 4.0 if text.endswith('то') else 2.0
    j = JAPANESE_CONTINUATIONS.search(text) if ord(text[-1]) > 0x3000 else None
    if j:
        value = 6.0 if j.group(2) in {'でも', 'にも', 'とか', 'ぞ'} else 3.5
    if text.endswith('くらい') and re.search(r'(?:どの|どれ)くらい$', text):
        value = -3.8
    if text[-1] in '的边邊地處' and re.search(
            r'怎[样樣]的$|哪[边邊]$|何[地處]$', text):
        value = -2.2
    return carry, float(value)

"""Detect the start of an English predication, especially a generic definition.

A recent determiner approximates subject definiteness: bare and indefinite
subjects get stronger signals than definite ones; pronouns get little.
Signal can continue onto defining complements. This is an approximation,
not a syntactic parser. Separate rules cover a few non-English
topic/copula markers, dotted leaders, and document-initial "Title:" headers.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
AUXILIARIES = set((
    'is are was were has have had do does did can could may might must '
    'will would should shall be been being '
).split())
SUBJECT_WORDS = set((
    'i you he she it we they there this that these those what who which one '
).split())
FUNCTION_WORDS = set((
    'the a an of to in for on with from by at as and or but if when where '
    'why how not no all both each every any some such than then '
).split())
DETERMINERS = set((
    'the a an this that these those my your his her its our their '
).split())
CLAUSE_WORDS = set((
    'because since although though while whereas if when that and or but '
).split())


# Expected strength for definite versus bare/indefinite nominal subjects.
LEVELS = {
    'is': (0.28, 0.82), 'are': (0.08, 0.85),
    'was': (0.24, 0.55), 'were': (0.09, 0.39),
    'has': (0.12, 0.32), 'have': (0.00, 0.20), 'had': (0.01, 0.10),
    'can': (0.10, 0.40), 'may': (0.23, 0.55),
    'will': (0.14, 0.24), 'would': (0.20, 0.30),
    'could': (0.01, 0.13), 'should': (0.06, 0.22),
    'might': (0.17, 0.47), 'must': (0.00, 0.15),
    'does': (0.15, 0.43),
}
DEFINING = set('refer mean denote signify represent constitute define'.split())


def continuation(word):
    if word in {'a', 'an', 'the'}:
        return 0.85
    if word == 'one':
        return 1.5
    if word == 'not':
        return 0.4
    if word in {'also', 'just', 'only', 'always', 'usually', 'never'}:
        return 0.7
    if word in {'defined', 'used', 'considered'}:
        return 1.0
    return {'be': 0.45, 'as': 0.7}.get(word, 0.0)


@lru_cache(maxsize=32768)
def verb_roots(word):
    return set(wordnet.base_forms(word, 'verb'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, determiner, previous_signal = '', '', 0.0
    fresh = carry is None or carry[0] != doc
    if not fresh:
        _, previous, determiner, previous_signal = carry
    token = prefix.token_strings[-1]
    word, previous_word = token.strip().lower(), previous.strip().lower()
    if fresh:
        subject_kind = 'start'
    elif previous_word in SUBJECT_WORDS:
        subject_kind = 'pronoun'
    elif previous_word in FUNCTION_WORDS or previous_word in AUXILIARIES:
        subject_kind = 'function'
    else:
        definite = determiner and determiner not in {'a', 'an'}
        subject_kind = 'definite' if definite else 'nominal'
    value = 0.0
    starts_word = token.startswith(' ')
    if starts_word and word in LEVELS:
        if subject_kind == 'pronoun':
            neutral = word in {'was', 'can', 'may', 'would', 'might'}
            value = 0.0 if neutral else -0.07
        elif subject_kind == 'function':
            value = 0.2 if word in {'is', 'was', 'were'} else -0.03
        elif subject_kind == 'start':
            value = -0.15
        else:
            value = LEVELS[word][0 if subject_kind == 'definite' else 1]
    elif starts_word and word in {'be', 'been', 'being', 'do', 'did'}:
        value = -0.03
    elif starts_word and word.isascii() and word.isalpha():
        bases = verb_roots(word)
        if bases & DEFINING:
            value = 0.0 if subject_kind in {'pronoun', 'function'} else 0.7
            if subject_kind == 'definite':
                value = 0.25
            if word == 'refers':
                value = 1.3 if subject_kind == 'definite' else 2.0
    if previous_signal > 0 and token.startswith(' '):
        value += continuation(word) * previous_signal
    if (token == ':' and previous == 'Title'
            and (prefix.position == 1 or (prefix.position > 1
                 and prefix.document_ids[-3] != doc))):
        value = -24.1
    if len(token) > 1 and set(token) == {'·'}:
        value = -1.0
    if word in ('は', 'も', 'とは'):
        value = {'は': 0.49, 'も': 0.22, 'とは': 1.18}[word]
    if word.startswith('是') or word in ('就是', '的是'):
        value = 0.5
    if word.startswith('作为') or word == '指的是':
        value = 1.3
    if word == 'это':
        value = 0.88
    # Reset the approximate noun phrase at clause or document boundaries.
    boundary = re.search(r'[.!?\n;,]', token) or token.startswith('<|')
    if boundary or word in CLAUSE_WORDS:
        determiner = ''
    if word in DETERMINERS:
        determiner = word
    state = (doc, token, determiner, min(4.0, max(0.0, value)))
    return state, float(value)

programs.haiku:
"""Generic-subject predicate detector.

The component fires on the verb that states a property of a noun subject, mostly the
copula: "Writing is ...", "a dog is ...", "Artificial intelligence is ...", "Influenza
activity is ...". Its response depends on the subject:
  - a bare noun or an indefinite one ("a", "an") gives the full response;
  - after punctuation (")" or ",") it is somewhat weaker;
  - a definite or possessive subject ("the/this/my/each ... is") gives little;
  - a pronoun subject ("it is", "there are", "they were") gives nothing;
  - in a where/if/when clause it is halved.
The article right after such a verb ("is a", "are the") also fires a little.
The colon in a "Title:" header at the very start of a document gives a very large
negative response (about -24), the largest value in the data.
"""

READS = ()

# typical response to a generic subject, per verb
VERB_WEIGHT = {
    # copula and modals
    " is": 0.85, " are": 0.85, " was": 0.5, " were": 0.4, " may": 0.5, " can": 0.45,
    " might": 0.4, " will": 0.25, " would": 0.3, " should": 0.3, " does": 0.3,
    " must": 0.15, " has": 0.3,
    # predicates that describe what a thing is or does
    " means": 0.55, " involves": 0.7, " requires": 0.65, " works": 0.6,
    " represents": 0.55, " allows": 0.55, " consists": 0.5, " provides": 0.45,
    " offers": 0.45, " depends": 0.45, " helps": 0.45, " appears": 0.4,
    " remains": 0.4, " occurs": 0.65, " defined": 0.4, " considered": 0.3,
}
ARTICLES = {" a", " an", " the"}
PRONOUNS = {"it", "there", "this", "that", "he", "she", "i", "they", "we", "you",
            "what", "who", "which", "these", "those", "here"}
DEFINITE = {"the", "this", "these", "those", "my", "your", "our", "their", "its", "his",
            "her", "each", "every", "first", "second", "last", "which", "where", "when", "if"}
INDEFINITE = {"a", "an"}
CONDITIONS = {"where", "if", "when"}


def subject_gate(toks):
    """How strongly the noun phrase just before the verb reads as a generic subject."""
    prev = toks[-2].strip().lower()
    if prev in PRONOUNS:
        return 0.0
    if not prev.replace("'", "").isalnum():
        return 0.6                       # the verb follows punctuation, e.g. ')' or ','
    for back in toks[-2:-6:-1]:          # walk back through the subject's words
        word = back.strip().lower()
        if word in DEFINITE:
            return 0.25
        if word in INDEFINITE:
            return 1.0
        if not word.replace("'", "").isalnum():
            break
    return 1.0                           # bare noun: a generic subject


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    tok = toks[-1]
    # position inside the current document (0 = its first token)
    doc_pos = 0
    while doc_pos < len(docs) - 1 and docs[-2 - doc_pos] == docs[-1]:
        doc_pos += 1
    if doc_pos == 1 and tok == ":" and toks[-2] == "Title":
        return None, -24.0
    if doc_pos == 0:
        return None, 0.0
    if tok in VERB_WEIGHT:
        gate = subject_gate(toks)
        if any(t.strip().lower() in CONDITIONS for t in toks[-4:-1]):
            gate *= 0.5
        return None, VERB_WEIGHT[tok] * gate
    if tok in ARTICLES and toks[-2] in VERB_WEIGHT:
        return None, 0.4
    return None, 0.0

programs.sol:
"""A coarse document-initial spelling and syntax approximation.

Use punctuation, indentation, word classes, L/T initials, and token length
at the start of each document. Preserve this value through an identical-token
initial run. Interior positions are zero except for lowercase Slovak ľ,
including its split UTF-8 spelling. Fine token-specific variation is omitted;
these are calibrated heuristics, not a complete account of the component.
"""
READS = ()

PREPOSITIONS = frozenset(('in', 'on', 'at', 'of', 'by', 'from', 'with', 'for'))
COPULAS = frozenset(('be', 'is', 'are', 'was', 'were', 'been', 'being'))
THIRD_PERSON = frozenset(('he', 'she', 'it', 'they'))
IMPORTS = frozenset(('package', 'import', 'using', 'include', 'require'))


def initial_value(token):
    word = token.strip()
    lower = word.lower()
    if token == '<|endoftext|>':
        return -2.67
    if word and set(word) == {'#'}:
        return {1: -0.91, 2: -1.50, 3: 0.68}.get(len(word), 0.0)
    if word and set(word) == {'·'}:
        return -1.19
    if len(word) >= 2 and set(word) == {'^'}:
        return -2.09
    if word == '_' and token.startswith(' '):
        return 1.07
    if word in ('\\n', '\\t', '\\"'):
        return -1.60
    if token.startswith('\\') and len(token) > 1:
        return -0.70
    if word.startswith(('"', '“')):
        return -0.55
    if word.startswith('#'):
        return -0.40
    if token and set(token) == {' '}:
        return min(0.35, 0.025 + 0.05 * len(token))
    if '\n' in token:
        return -0.15
    if word.isdecimal():
        return -0.06
    if word == ':':
        return 0.47
    if word.startswith(')'):
        return -0.25
    if word.startswith('.'):
        return -0.15
    if lower in IMPORTS:
        return -0.40
    if word == 'def':
        # Indented Python definitions differ from the bare fragment.
        return 1.35 if token[:1].isspace() else -0.12
    if lower == 'class':
        return 0.46
    if lower == 'function':
        return -0.42
    if lower in THIRD_PERSON:
        return -0.45
    if lower in ('i', 'you'):
        return 0.45
    if lower in COPULAS:
        return -0.35
    if lower in PREPOSITIONS:
        return -0.22
    if lower in ('when', 'after', 'before', 'while', 'since', 'until'):
        return -0.45
    if lower == 'to':
        return 0.95 if token == word else 0.39
    if lower == 'the':
        return 0.26 if token.startswith(' ') else 0.07
    if lower == 'a':
        return -0.03 if token.startswith(' ') else -0.50
    if lower == 'an':
        return 0.55
    if lower in ('and', 'or', 'but', 'nor'):
        return 0.15
    if lower.startswith('l'):
        return 0.41 if len(word) <= 3 else 0.10
    if lower.startswith('t') and len(word) <= 3:
        return 0.21
    return -0.08 if len(word) >= 4 else 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        same_initial = True
    else:
        same_initial = carry[2] and token == carry[1]
    value = initial_value(token) if same_initial else 0.0
    # Complete the Slovak lowercase L-with-caron even when UTF-8 is split.
    if token == 'ľ' or (
        prefix.position > 0 and prefix.token_bytes[-1] == b'\xbe'
        and prefix.token_bytes[-2].endswith(b'\xc4')
        and prefix.document_ids[-2] == document
    ):
        value = 0.50
    return (document, token, same_initial), value

programs.haiku:
"""Digits after the dot of a version number such as repo__1.0, pkg-2.1.3, v0.5 or Python 3.10
are strongly negative; the dots of such numbers mildly so. Other decimals stay near zero."""
READS = ()
DIGITS = "0123456789"
GLUED = {"__", "-", "@", "/", "'", '"', "v", " v", "rb-"}
VERSION_WORDS = {"Python", "License", "version", "Version", "release"}

def step(carry, prefix, upstream):
    s = prefix.token_strings
    cur = s[-1]
    if cur not in DIGITS and cur != ".":
        return carry, 0.0
    i = len(s) - 1
    while i >= 0 and (s[i] in DIGITS or s[i] == "."):
        i -= 1
    number = s[i + 1:]
    if "." not in number or i < 0:
        return carry, 0.0
    before = s[i]
    near = [t.strip() for t in s[max(0, i - 3):i + 1]]
    if before not in GLUED and not any(t in VERSION_WORDS for t in near):
        return carry, 0.0
    if cur == ".":
        return carry, -0.3
    return carry, -1.2 if len(s) >= 2 and s[-2] == "." else 0.0

programs.sol:
"""Recognize opening Title: headers and a few source-code word patterns.

The colon immediately after document-initial 'Title' is exceptional. The
other main response is to 'use' in import statements and React hook names,
not the ordinary English verb. Numbered or escaped code is weaker. Global
declarations, styled-components bindings and line-initial flex get
smaller responses, using punctuation and whitespace as cues rather than a
parser. Document starts have a slightly elevated background; most other
tokens receive a near-zero value. Only the last 512 characters are retained.
"""
import re

READS = ()


def predict(token, before, position, previous):
    if position == 0:
        if token == 'Title':
            return -1.062
        if token == 'use':
            return -0.116
        if token == ' use':
            return 0.468
        return 0.10 if token.startswith(' ') else 0.02
    if position == 1 and previous == 'Title' and token == ':':
        return 16.835

    word = token.strip()
    if word not in {'use', 'global', 'styled', 'flex'}:
        return -0.005

    line = before.rsplit('\n', 1)[-1]
    numbered = bool(re.fullmatch(r'[ \t]*\d+[ \t]*', line))
    numbered = numbered and ('\t' in line or token.startswith('\t'))
    line_start = bool(re.fullmatch(r'[ \t]*', line))
    escaped_start = bool(re.search(r'\\n[ \t]*$', before))
    code = any(mark in before for mark in
               ('::', '<?php', 'namespace ', ';\n', ';\r\n', '```',
                'quote!', 'mod ', 'perl', 'EOF', '//!', '*/'))
    line = line.rsplit(r'\n', 1)[-1]

    if word == 'use':
        if numbered:
            return 0.45
        if re.search(r'\b(?:import|export)\s*\{\s*$', line):
            return 1.65
        if re.search(r'\b(?:import|export)\s*\{[^}]*$', line):
            return 0.90
        if re.search(r'\bimport\s*$', line):
            return 0.95
        if re.search(r'\b(?:const|let|var)\b.*=\s*$', line):
            return 1.40
        if line_start and code:
            if token == 'use' or token == '\tuse':
                php = ('<?php' in before or 'namespace ' in before or
                       ('\\' in before and '::' not in before))
                return 1.95 if php else 1.25
            return 0.80
        if line_start and '\n' in before and len(line) >= 2:
            return 0.85
        if line.rstrip().endswith(';') and code:
            return 1.10
        if re.fullmatch(r'[ \t]*[+-][ \t]*', line) and code:
            return 1.10
        if escaped_start:
            return 0.12 if token == 'use' else 0.65
        if token == ' use' and line.rstrip().endswith(':'):
            return 0.25
        return -0.07 if token == ' use' else 0.0

    if not token.startswith((' ', '\t')):
        return -0.005
    if word == 'global':
        return 0.50 if line_start and '\n' in before else -0.06
    if word == 'styled':
        if re.search(r'\bimport\s*$', line):
            return 0.90
        return 0.75 if line.rstrip().endswith('=') else -0.10
    if line_start and '\n' in before:
        return 0.60
    return 0.08 if line.rstrip().endswith(':') else -0.015


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        before, position, previous = '', 0, ''
    else:
        _, before, position, previous = carry
        position += 1
    value = predict(token, before, position, previous)
    return (doc, (before + token)[-512:], position, token), value

"""GitHub/domain and package-path endings, with a document-start correction.

The largest positive response marks `.com` in GitHub addresses. Other
Internet suffixes, URL separators, and namespace roots respond weakly.
The response is usually near zero, but is negative on document starts
and on repeated middle-dot separator tokens.
"""

import re

READS = ()
DOMAIN_SUFFIXES = {".com", ".org", ".net", ".edu", ".gov", ".io"}
NAMESPACE_ROOTS = {"com", "org", "io", "cn"}


def start_value(token):
    text = token.strip()
    if not text:
        return -0.01
    if text.startswith("<"):
        return -0.10
    if text.isdigit():
        return -0.21
