programs.sol:
"""Detect symbolic starts: unary signs, punctuation literals, and operator names.

A minus introducing a value differs from a minus between operands. Similarly,
a slash or underscore starting a path/name differs from one inside a word.
The strongest negative responses are for symbols inside newly opened strings
and for C++ overloaded-operator names. Unrecognized positions stay near zero.
Only the last two tokens are retained; state resets between documents.
"""
READS = ()

VALUE_WORDS = frozenset('''
a an the is are was were be being been equal equals to of from at by for
with without and or than as versus vs not then return yield case
'''.split())
QUOTES = '\'"“‘'
STRING_PREFIXES = {'f', 'r', 'b', 'u', 'fr', 'rf', 'br', 'rb'}
VALUES = {
    'ordinary': 0.0,
    'literal_escape': -3.7,
    'literal_space': -3.3,
    'literal_empty': -1.4,
    'literal_symbol': -1.3,
    'literal_closed_symbol': -2.8,
    'literal_spaced_symbol': -0.2,
    'single_backslash': -1.3,
    'trailing_quote_escape': -0.5,
    'quote_marker': -1.9,
    'url_scheme': -1.05,
    'escape_letter': -0.7,
    'operator_name': -6.5,
    'embedded_sign': -0.7,
    'introduced_sign': -1.95,
    'punctuation_sign': -1.8,
    'math_sign': -0.8,
    'underscore_prefix': -0.6,
    'tilde_prefix': -0.6,
    'html_entity': -1.0,
    'path_start': -1.1,
    'other_unary': -0.35,
    'tex_comparison': -0.2,
}


def opens_quote(token, before):
    if not token or token[-1] not in QUOTES:
        return False
    body = token[:-1].rstrip('\\')
    if body:
        return (body[-1].isspace() or body[-1] in '([{=:,+'
                or body.strip().lower() in STRING_PREFIXES)
    return not before or not (before[-1].isalnum() or before[-1] in ')]}')


def category(token, prev, before):
    s = token.strip()
    p = prev.rstrip()
    if not s:
        return 'ordinary'
    word = p.strip().lower()
    last = p[-1:]
    spaced = token.startswith(' ')
    punctuation = not any(ch.isalnum() for ch in s)

    if (p.strip() == 'operator' and punctuation and not spaced
            and s[0] in '=+-*/%&|^~!<>()[]'):
        return 'operator_name'

    if opens_quote(prev, before):
        if s in ('http', 'https'):
            return 'url_scheme'
        if punctuation:
            if s[0] == '\\':
                if not s.strip('\\'):
                    return ('single_backslash' if len(s) == 1
                            else 'literal_escape')
                return ('trailing_quote_escape' if s.endswith('\\')
                        else 'quote_marker')
            if s[0] in '\'"':
                return 'literal_space' if spaced else 'literal_empty'
            if any(ch in '\'"”’' for ch in s[1:]):
                return 'literal_closed_symbol'
            return ('literal_spaced_symbol' if spaced
                    else 'literal_symbol')

    if s in ('n', 't', 'r') and p.endswith('\\'):
        if (opens_quote(p.rstrip('\\'), before)
                or (not p.rstrip('\\') and opens_quote(before, ''))):
            return 'escape_letter'

    # An opening delimiter and minus may be packed into the same token.
    body = s.lstrip('=(:,[{')
    if body[:1] in ('-', '−', '±'):
        if body != s:
            return 'embedded_sign'
        if '\n' in prev:
            return 'ordinary'
        if last and last in '=<>:([{,≠≈≤≥':
            return 'punctuation_sign'
        if last and last in '$^|':
            return 'math_sign'
        if last and last in QUOTES and not spaced:
            return 'literal_symbol'
        if spaced and word in VALUE_WORDS and len(word) > 1 and len(s) == 1:
            return 'introduced_sign'

    if spaced:
        if s.startswith('_'):
            return 'underscore_prefix'
        if s.startswith('~'):
            return 'tilde_prefix'
        if s.startswith('&#'):
            return 'html_entity'
        if s == '/' and (last == ':' or word in VALUE_WORDS):
            return 'path_start'
        if s in ('+', '*', '|', '%', '#', '@', '≤', '≥', '←'):
            if word in VALUE_WORDS or last in ('=', ':', ',', '('):
                return 'other_unary'
    if s in ('le', 'leq', 'ge', 'geq') and p.endswith('\\'):
        return 'tex_comparison'
    return 'ordinary'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev = before = ''
    else:
        _, prev, before = carry
    token = prefix.token_strings[-1]
    return (doc, token, prev), VALUES[category(token, prev, before)]

programs.haiku:
"""Minus signs that open a negative number, and escaped quotes that open a string in code.

Component layers.1.mlp.down_proj:2129 writes a negative value into the residual stream
when it fires, and it fires on very few tokens. The biggest firings are a minus sign that
begins a negative quantity in arithmetic or assignment text: "= -4", "or -1", "and -2",
", -3", "(-2)". A minus that subtracts (after a number, a name or a closing bracket, as in
"3 - 2" or "f(x) - 1") barely moves it, and dashes in prose are weak. A smaller firing
comes from an escaped quote or backslash that opens a string literal inside code text,
such as print(\\" or ("\\\\.
"""

READS = ()

MINUS = {"-", "−", "–", "—"}
PLUS = {"+"}
# Words and punctuation after which a minus sign opens a negative number.
BEFORE_NEGATIVE = {"=", ",", ":", "is", "and", "or", "with", "(", "to", "be", "≈", "≤", "≥"}


def _bare(token):
    """The token without its leading space and any opening bracket or quote glued to it."""
    token = token.lstrip(" ")
    while len(token) > 1 and token[0] in "([{=,:\"'":
        token = token[1:]
    return token


def _ends_operand(token):
    """True if the token ends a number, a name or a closing bracket, so a minus after it subtracts."""
    token = token.rstrip()
    return bool(token) and (token[-1].isalnum() or token[-1] in ")]}\"'`_")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_doc = len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]
    before = "" if new_doc else prefix.token_strings[-2]
    before_bare = before.strip()
    math_before = before_bare in BEFORE_NEGATIVE or before_bare.endswith("=")
    if _bare(token) in MINUS:
        if math_before:
            value = -1.5
        elif _ends_operand(before):
            value = -0.06
        else:
            value = -0.28
    elif _bare(token) in PLUS and math_before:
        value = -0.9
    elif "\\" in token and (before_bare in ("(", "[") or before_bare.endswith('"')):
        value = -0.8
    else:
        value = 0.0
    return carry, value

