    elif word == '待':
        value = -3.1
    elif word == '対':
        value = -2.6
    elif word == '帯':
        value = -3.5
    elif word == '介':
        value = -1.5
    elif word in ('带', '帶', '戴'):
        value = -1.7
    elif word in (
        '现代', '現代', '古代', '当代', '當代', '年代',
        '代理', '代替',
