    elif re.fullmatch(r'[一二三四五六七八九十]代', word):
        value = -2.2
    elif '代' in word and word not in ('代码', '代碼'):
        value = -0.45
    elif word in ('接待', '招待', '热带', '熱帶'):
        value = -2.3
    elif word == '대한':
        value = -0.55
    elif word == '대로':
        value = -2.5
    elif word in ('たい', 'ダイ'):
        value = -1.1 if word == 'たい' else -1.7
    elif word == 'Dai':
        value = -5.3
    elif word == 'Đại':
        value = -3.6
    elif word == 'dae':
        value = -3.1
    elif word == 'dai':
        value = -1.0
    elif token in ('ai', 'ae'):
        value = -0.05
        if previous.lower().endswith('d'):
            value = -3.9 if token == 'ai' else -1.6
        elif token == 'ai' and previous.lower().endswith(('t', 'w')):
            value = -0.5
    elif token.startswith('ai') and previous.lower().endswith('d'):
        value = -0.7  # diluted inside a longer token
    elif word == 'e' and previous.lower().endswith('ida'):
        value = -1.3
    elif word == 'ï' and previous.lower().endswith('da'):
        value = -3.4
    elif word in ('い', 'イ'):
        value = -0.1
        name = unicodedata.name(previous[-1], '') if previous else ''
        script = 'HIRAGANA' if word == 'い' else 'KATAKANA'
        if name.startswith(script):
            syllable = name.split()[-1]
