"""Approximate a local collection, iteration, and binding cue.

Large pulses mark iterable spellings, mathematical membership, and loop-header
angle brackets. Binding operators and length cues receive smaller responses;
minus signs starting diff hunks also receive a pulse. Code-like context
separates iteration's `in` from the ordinary preposition, and suppresses likely
infinity notation. Each class has a fixed average strength. Most other tokens
stay near zero. A 200-character history is reset at document boundaries.
"""
import re

READS = ()
STRENGTH = {
    'loop iterable': 11.4,
    'membership test': 5.8,
    'negated membership': 8.0,
    'prose in': -0.04,
    'latex membership': 5.4,
    'membership symbol': 4.1,
    'Go range': 11.5,
    'Python range': 3.3,
    'enumerate': 4.6,
    'loop bound': 6.9,
    'while bound': 2.5,
    'early for header': 3.0,
    'conditional bound': 1.3,
    'inequality': 0.06,
    'for colon': 8.5,
    'loop binding': 0.5,
    'Go loop binding': 3.6,
    'Go binding': 1.0,
    'assignment': 0.38,
    'short assignment': 0.05,
    'field assignment': -0.1,
    'length test': 1.7,
    'length expression': 0.55,
    'diff hunk': 1.65,
}

# Python unpacking and C#/JavaScript typed loop variables.
LOOP_VAR = re.compile(
    r'\b(?:for\s+(?:\(\s*)?\w+(?:\s*,\s*\w+)*\s*\)?'
    r'|(?:for|foreach)\s*\(\s*(?:[\w.<>\[\]]+\s+)?\w+)\s*$'
)
CONDITION = re.compile(r'\b(if|elif|while|assert|return)\b\s*([^:\n{};]*)$')


def code_prefix(text, start):
    """A statement starts a code line; comprehensions sit inside expressions."""
    head = text[:start].rsplit('\n', 1)[-1]
    if not head.strip(' \t0123456789+->|`'):
        return True
    if head.count('"') % 2 or head.count("'") % 2:
        return False
    if head.rstrip().endswith((';', '{', '}')):
        return True
    if head.count('[') > head.count(']') or head.count('(') > head.count(')'):
        return True
    return (head.count('{') > head.count('}')
            and ('=' in head or 'return' in head or head.lstrip().startswith('{')))



def loop_variable(before):
    match = LOOP_VAR.search(before)
    return bool(match and ('(' in match[0] or code_prefix(before, match.start())))


def condition(before):
    match = CONDITION.search(before)
    if not match or not code_prefix(before, match.start()):
        return False
    expression = match[2].strip()
    return bool(expression and len(expression) < 100
                and (re.fullmatch(r'[(!\s]*(?:not\s+)?\w+(?:\s+not)?[)\s]*', expression)
                or re.search(r"\w[._]\w|\w+\(|[\[\]'\"]", expression)))


def concept(token, before):
    word = token.strip()
    before = re.sub(r'\\([nt])(?=\s|\\|(?:for|foreach|if|elif|while|assert|return)\b)',
                    lambda m: '\n' if m[1] == 'n' else '\t', before)
    if (word in ('in', 'notin') and not token[:1].isspace()
            and re.search(r'\\(?:<)?$', before.rstrip())):
        if re.search(r'(?:[\^=<>≤≥+−-]|\bto|\brightarrow|\bleq?|\bgeq?)\s*\\+$', before):
            return '', 0.0
        return 'latex membership', 1.0
    if word == '∈':
        return 'membership symbol', 1.0
    if word in ('in', 'of') and token[:1].isspace():
        if loop_variable(before) and (word == 'in' or re.search(r'\bfor\s*\(', before)):
            return 'loop iterable', 1.0
        if word == 'in':
            if re.search(r'\bnot\s*$', before) and condition(before):
                return 'negated membership', 1.0
            if condition(before):
                return 'membership test', 1.0
            return 'prose in', 1.0
    if word == 'range':
        if re.search(r':=\s*$', before):
            return 'Go range', 1.0
        if re.search(r'\bin\s*$', before) and token[:1].isspace():
            return 'Python range', 1.0
    if word == 'enumerate' and re.search(r'\bin\s*$', before):
        return 'enumerate', 1.0
    if re.fullmatch(r'<[A-Za-z_]*', word):
        scale = 1.0 if word == '<' else 0.5
        if re.search(r'\bfor\b[^\n{}]*;[^;\n{}]*$', before):
            return 'loop bound', scale
        if re.search(r'\bfor\s*\([^;{}\n]*$', before):
            return 'early for header', scale
        if re.search(r'\bwhile\s*\([^{}\n]*$', before):
            return 'while bound', scale
        if condition(before):
            return 'conditional bound', scale
        if token[:1].isspace():
            return 'inequality', scale
    if word == ':' and re.search(r'\bfor\s*\([^;{}:\n]*$', before):
        return 'for colon', 1.0 if token[:1].isspace() else 0.1
    if word in ('=', ':='):
        if loop_variable(before):
            return ('Go loop binding' if word == ':=' else 'loop binding'), 1.0
        if word == ':=':
            return 'Go binding', 1.0
        if token[:1].isspace():
            if re.search(r'(?:\.[\w]+|\])\s*$', before):
                return 'field assignment', 1.0
            name = re.search(r'\b([\w]+)\s*$', before)
            if name and len(name[1]) > 1 and name[1].isidentifier():
                return 'assignment', 1.0
            return 'short assignment', 1.0
    if word == 'len' and token[:1].isspace():
        if re.search(r'(\b(if|elif|assert|while)|[=<>!]=?)\s*$', before):
            return 'length test', 1.0
        return 'length expression', 1.0
    if word == '-' and re.search(r'@@\s*$', before):
        return 'diff hunk', 1.0
    return '', 0.0


def predict(token, before):
    name, scale = concept(token, before)
    return STRENGTH.get(name, 0.0) * scale


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(token, before)
    return (doc, (before + token)[-200:]), value

programs.haiku:
"""Loop binders: the token that says what a `for` loop iterates over.

This component fires on the word or operator that comes right after the loop
variable(s) of a code `for` loop header, and on membership written as LaTeX `\\in`
or Isabelle `\\<in>`. Its activation (in units of the residual stream) is roughly:

  for x in xs              `in`     about 13  (Python; also C# `foreach (T x in xs)`)
  for (T x : xs)           `:`      about 8   (Java / C# foreach with a colon)
  for (i = 0; i < n; ...)  `<`      about 8   (C-style counting loop)
  for i, x := range xs     `range`  about 10  (Go)
  for i in range(n)        `range`  about 3   (Python)
  $x \\in S$                `in`     about 4.5 (math membership)
  if k in d                `in`     about 1   (weak)

Everything else is 0, including `in` in ordinary prose ("results in") and `for`
in prose ("for use"). Literal "\\n" and backticks in the text are read as line
breaks and spaces, so markdown and escaped code are handled too.
"""
import re

READS = ()

# the current line ends with a loop header: `for`/`foreach`, an optional `(`, an
# optional type, then the loop variable(s) and nothing else. Also a `for` inside a
# bracketed comprehension, e.g. `[f(x) for x in`.
LOOP_VARS = (
    r"\bfor(?:each)?\b\s*\(?\s*(?:[\w<>\[\]*&.]+\s+)?[\w\[\]]+(?:\s*,\s*[\w\[\]]+)*\s*$"
)
HEADER = re.compile(
    r"(?:^|[(\[{=;]|\)\s|\]\s|\}\s)\s*" + LOOP_VARS + r"|[\[{][^\]}]*\s" + LOOP_VARS
)
GO_RANGE = re.compile(r"\bfor\b[^\n]*:=\s*$")  # `for i, x := range`
C_LOOP = re.compile(r"\bfor\b[^\n]*;\s*\w+\s*$")  # `for (i = 0; i <`
IF_TEST = re.compile(r"\b(?:if|elif)\b[^\n]*$")  # `if k in d`
STRENGTH = {"in": 13.0, ":": 8.0, "range": 3.0}


def _plain(text):
    return text.replace("\\n", "\n").replace("\\t", " ").replace("`", " ").replace("\xa0", " ")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "line": "", "prev": ""}
    tok = prefix.token_strings[-1]
    word = tok.strip()
    line, prev = carry["line"], carry["prev"]

    value = 0.0
    if word in STRENGTH and HEADER.search(line):
        value = STRENGTH[word]
    elif word == "range" and GO_RANGE.search(line):
        value = 10.0
    elif re.fullmatch(r"[<>]=?\w*", word) and C_LOOP.search(line):
        value = 8.0
    elif word == "in" and prev.endswith(("\\", "\\<")):
        value = 4.5
    elif word == "in" and IF_TEST.search(line):
        value = 1.0

    line = _plain(line + tok)
    line = line.split("\n")[-1][-200:]
    return {"doc": doc, "line": line, "prev": tok}, value

