"""A lexical-grammar approximation of linked English verb constructions.

Lower-case 'to' receives a negative value after common infinitive governors:
want/need, attempts, beginnings, failures, remembering, and so on. Strength
also depends on verb form and a few local grammatical cues. Sentence-initial
'To' and coordinated 'and/or to' have positive values. A few familiar idioms
(end up, take care, cannot help but) receive negative values on their linker.
Other tokens are left at zero; this does not model the multilingual tail.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

# Infinitive governors, grouped by familiar kinds of construction.
GOVERNORS = (
    (-1.0, 'want need wish'),                 # desire and necessity
    (-1.3, 'have'),                          # obligation: have to
    (-1.8, 'try attempt decide intend elect'),
    (-3.0, 'start begin continue'),           # phases of an action
    (-4.4, 'fail neglect'),                  # failure to act
    (-3.5, 'refuse decline hesitate cease'),  # withholding an action
    (-3.3, 'choose prefer'),
    (-2.8, 'hope expect promise offer prepare'),
    (-4.7, 'manage afford bother'),
    (-5.8, 'threaten'),
    (-8.0, 'forget'),                        # remembering to do something
    (-5.5, 'remember'),
    (-4.1, 'learn'),
    (-3.2, 'love hate sure'),
    (-1.8, 'help happen tend seem'),
    (-1.2, 'like know appear claim agree deserve proceed'),
    (-1.6, 'failure afraid'),
    (-0.8, 'nothing happy glad pleased free careful wait'),
    (-0.4, 'able unable ready willing likely possible necessary time effort'),
    (-0.7, 'aim seek plan strive'),
)
GOVERNORS = tuple((value, frozenset(words.split()))
                  for value, words in GOVERNORS)

@lru_cache(maxsize=4096)
def governor(word):
    bases = set(wordnet.base_forms(word, 'verb')) | {word}
    value = next((v for v, words in GOVERNORS if bases & words), 0.0)
    # Verb forms differ substantially, especially the progressive 'trying to'.
    if word.endswith('ing'):
        if 'try' in bases:
            value *= 0.27
        elif bases & {'learn', 'begin'}:
            value *= 0.65
        elif 'help' in bases:
            value = -4.0
        elif 'have' in bases:
            value = -4.2
    elif word.endswith('s'):
        if bases & {'need', 'seem', 'appear', 'tend', 'continue', 'choose'}:
            value *= 0.7
    if word.endswith('ed') or word in ('forgot', 'forgotten', 'began', 'chose'):
        value *= 0.8
    if word in ('hoped', 'expected'):
        value *= 0.6
    return value


@lru_cache(maxsize=4096)
def verb_bases(word):
    return set(wordnet.base_forms(word, 'verb')) | {word}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    match = re.search(r"([A-Za-z]+)[\s\"'’”)]*$", history)
    previous = match.group(1) if match else ''
    word = previous.lower()
    value = 0.0
    if token in (' to', 'to', ' To', 'To'):
        if token.strip() == 'To':
            boundary = not history or bool(re.search(r'[.!?:;\n\-•]\s*$', history))
            value = 0.78 if boundary else 0.15
        elif token == 'to' and history and not history[-1].isspace():
            value = 0.16  # part of a word or identifier, rather than a linker
        elif history.rstrip().endswith((',', ';', ':')):
            value = 0.53
        elif word in ('and', 'or', 'but', 'so'):
            value = 0.9
        elif word in ('how', 'what', 'where', 'when', 'whether'):
            value = -1.5 if previous.islower() else -0.65
        elif word in ('yet', 'best'):
            value = -1.1
        elif word in ('on', 'out'):
            value = -0.4
        elif word == 'not':
            earlier = re.findall(r'[A-Za-z]+', history)[:-1]
            prior = earlier[-1].lower() if earlier else ''
            value = 0.35
            if verb_bases(prior) & {'decide', 'choose', 'try', 'careful', 'tend'}:
                value = 0.7 * governor(prior)
        else:
            value = governor(word)
            if re.search(r'\b(will|would|may|might|must|shall|should|could|can) '
                         r'(?:[A-Za-z]+ )?' + re.escape(previous) + r'$', history, re.I):
                if value < -0.5:
                    value -= 0.6
            if word.endswith('ed') and re.search(
                    r'\b(be|been|being|is|are|was|were) (?:[A-Za-z]+ )?'
                    + re.escape(previous) + r'$', history, re.I):
                value = -0.15
            if word in ('need', 'plan', 'plans', 'attempt') and re.search(
                    r'\b(a|an|the|my|your|his|her|their|our|of) '
                    + re.escape(previous) + r'$', history, re.I):
                value = -0.2
    elif token.startswith(' '):
        current = token.strip().lower()
        bases = verb_bases(word)
        if current == 'but' and 'help' in bases:
            value = -7.0
        elif current == 'up' and 'end' in bases:
            value = -0.85 if word in ('ended', 'ends', 'ending') else -1.5
        elif current == 'care' and 'take' in bases:
            value = -2.2
        elif current == 'about' and bases & {'go', 'set'}:
            value = -0.6 if word.endswith('ing') else -2.5
        elif current == 'out' and bases & {'turn', 'set'}:
            value = -0.5
        elif current == 'on' and bases & {'go', 'keep'} and word != 'going':
            value = -1.0
        elif current == 'by' and bases & {'begin', 'start'}:
            value = -1.6
        elif current == 'not' and bases & {'decide', 'choose', 'careful'}:
            value = -2.0
        elif current == 'time' and re.search(
                r'\b(take|takes|taking|took|taken) the$', history, re.I):
            value = -1.5
        elif current == 'and' and bases & {'try', 'go'}:
            value = -2.2
        elif current == 'ahead' and word == 'go':
            value = -2.8
        elif current == 'is' and word == 'do':
            value = -1.8
    return (document, (history + token)[-120:]), value

programs.haiku:
"""Layer 1 MLP down-projection, component 2133: the "bare-verb is coming" particle detector.

It is strongly negative on the word "to" when "to" introduces an infinitive whose verb
is still to come, and the size of the dip depends on the word before it:
  "forget to" (about -8), "continue/fail/manage/choose/start/learn to" (about -3 to -4),
  "need/have/want/try/how to" (about -1.5), and a bit more after a modal ("will need to").
Ordinary prepositional "to" ("access to", "according to") gives ~0; "and to" / "or to" is
mildly positive, and a sentence-initial "To" (purpose infinitive) is mildly positive.
A few non-English and idiomatic particles that also introduce a bare verb get the same
treatment: "can't help but", Spanish "tener/hay que", "dejar de", Portuguese "começou a".

The program reads only the previous one or two tokens; it has no state.
"""

READS = ()

# Verbs/adjectives after which "to" starts an infinitive, grouped by how strongly.
STRONG = {"forget", "forgot", "forgetting", "remember", "remembered", "choose", "chose", "chooses",
          "chosen", "continue", "continued", "continues", "continuing", "fail", "failed", "fails",
          "failing", "manage", "managed", "manages", "managing", "start", "started", "starts",
          "starting", "begin", "began", "begins", "beginning", "learn", "learned", "learning",
          "refuse", "refused", "refuses", "threatened", "afford", "offered", "promised",
          "hesitate", "declined", "cease", "love", "hate", "sure"}
MEDIUM = {"need", "needed", "needs", "have", "has", "had", "having", "want", "wanted", "wants",
          "try", "tried", "trying", "decide", "decided", "decides", "help", "like", "seem", "seemed",
          "seems", "tend", "tends", "attempt", "wish", "hope", "how", "what"}
WEAK = {"able", "unable", "going", "best", "expected"}
DEJAR_DE = {"dejar", "dejó", "deja", "dejará", "acabar", "acabó", "tratar", "trata", "trató"}
TENER_QUE = {"hay", "tener", "tengo", "tienes", "tiene", "tenemos", "tienen", "tenía", "habría"}
MODALS = {"will", "would", "may", "might", "can", "could", "should", "must", "shall", "'ll", "’ll"}


def verb_value(word):
    if word in STRONG:
        return -3.5
    if word in MEDIUM:
        return -1.5
    if word in WEAK:
        return -0.5
    return 0.0  # prepositional or unknown: no contribution


def step(carry, prefix, upstream):
    s = prefix.token_strings
    if len(s) < 2:
        return None, 0.0
    cur = s[-1]
    prev = s[-2].strip().lower()
    if cur == " to":
        if prev in ("and", "or"):
            return None, 1.0
        if prev == ",":
            return None, 0.5
        value = verb_value(prev)
        # a modal two words back ("will need to") deepens the dip
        if len(s) > 2 and s[-3].strip().lower() in MODALS and value < 0:
            value *= 1.3
        return None, value
    if cur.strip() == "To":  # sentence-initial purpose infinitive
        return None, 0.6
    if cur == " de" and prev in DEJAR_DE:
        return None, -4.0
    if cur == " a" and prev in {"comenzó", "comenzar", "empezó", "começou", "começar", "ajudar"}:
        return None, -3.0
    if cur == " but" and prev == "help":  # "can't help but feel"
        return None, -6.0
    if cur == " que" and prev in TENER_QUE:
        return None, -5.0
    return None, 0.0

programs.sol:
"""Approximate a local start/progression and spelling-fragment response.

The largest English responses distinguish 'start to' (negative) from 'start
by/off/out' (positive). Other fixed phrases have smaller responses. A second
branch recognizes short st/ti spelling fragments, not complete words; it uses
transliteration to include related spellings in other alphabets. Greek
iota/tau sequences are tracked across token boundaries separately from eta.
Repeated literal backslash-t escapes are positive. Unrecognized contexts predict zero.
These are local approximations, not a claim of one unified semantic feature.
"""
from functools import lru_cache
import unicodedata
from anyascii import anyascii
import wordnet

READS = ()
START = {'start', 'starts', 'started', 'starting'}
BEGIN = {'begin', 'begins', 'began', 'beginning', 'begun'}
CONTINUE = {'continue', 'continues', 'continued', 'continuing', 'ceased'}
DETERMINERS = {'a', 'an', 'the', 'this', 'that', 'my', 'our', 'their', 'his', 'her'}
PHRASES = {
    ('most', 'of'): 1.8,
    ('most', 'often'): 1.8,
    ('best', 'known'): 3.5,
    ('better', 'known'): 1.5,
    ('best', 'of'): 0.7,
}


@lru_cache(maxsize=32768)
def local(previous, token):
    p, w = previous.strip().lower(), token.strip().lower()
    if p in START or p in BEGIN:
        if w == 'to':
            if p == 'beginning':
                return -2.0
            return -4.5 if p == 'starting' else -6.1
        if w == 'by':
            return (5.5 if p == 'start' else 4.4) if p in START else 2.8
        if w == 'off':
            return 8.5 if p == 'starting' else 6.5
        if w == 'out':
            return 3.3 if p == 'start' else 5.5
        if w == 'over':
            return 3.0
        return {'at': -3.3, 'from': -3.4,
                'with': -1.1 if p in START else -0.6}.get(w, 0.0)
    if p in CONTINUE and w == 'to':
        return -0.95
    if (p, w) in PHRASES:
        return PHRASES[p, w]
    if p in {'end', 'ends', 'ending', 'ended'} and w == 'up':
        return 1.1 if p == 'ended' else 0.4
    if p in {'finish', 'finished', 'finishes', 'finishing'} and w == 'off':
        return 1.0
    if token == '\\t' and previous in {'\\t', 't'}:
        return 3.5 if previous == '\\t' else 2.4
    if w in {'starter', 'starters'}:
        return 4.3
    if w == 'started' and p in {'get', 'getting', 'got', 'gets'}:
        return 4.0
    if w == 'stuck':
        return 3.9 if p in {'get', 'getting', 'got', 'become', 'became'} else 1.8

    # Preserve leading spaces: these tests join pieces within a word only.
    a, b = anyascii(previous).lower(), anyascii(token).lower()
    if a.endswith('st'):
        if b == 'it':
            return -10.5 if previous.isascii() else -6.0
        if b in {'itu', 'itution'}:
            return -7.0 if b == 'itu' else -2.6
        if b == 'im':
            return -5.4 if p == 'best' else -3.5 if p == 'st' else -1.5
        if b in {'imm', 'ime'}:
            return -2.0
        if b == 'at':
            return -1.8
        if b.startswith(('eh', 'ep', 'et', 'eng')) and len(b) <= 4:
            return 2.0
        if a.strip(' _-') == 'st' and b.startswith(
                ('ad', 'amm', 'off', 'uck', 'ung', 'und')):
            return 1.8
    if a.endswith('ste') and b in {'ck', 'pp'}:
        return 2.0
    if a.endswith('t') and b == 'it':
        return -2.5
    if w in {'stit', 'constit', 'instit', 'substit', 'restit'}:
        return -1.4
    if w in {'stim', 'estim', 'destin', 'stip', 'tit'}:
        return -1.5
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = ''
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == doc:
        previous = prefix.token_strings[-2]
    value = local(previous, token)
    # A noun phrase ('a successful start to ...') is not the verb 'start to'.
    if previous.strip().lower() == 'start' and token.strip().lower() == 'to':
        if len(prefix.token_ids) > 2 and prefix.document_ids[-3] == doc:
            before = prefix.token_strings[-3].strip().lower()
            pos = wordnet.parts_of_speech(before)
            determiner = (len(prefix.token_ids) > 3
                          and prefix.document_ids[-4] == doc
                          and prefix.token_strings[-4].strip().lower() in DETERMINERS)
            if before in DETERMINERS or ('adjective' in pos
                    and ('adverb' not in pos or determiner)):
                value = -0.6
            elif before == 'from':
                value = -2.5
    # Greek iota and eta transliterate alike, but have different responses.
    if token and all('GREEK' in unicodedata.name(c, '') for c in token):
        recent = ''.join(prefix.token_strings[j] for j in
                         range(max(0, len(prefix.token_ids) - 5),
                               len(prefix.token_ids) - 1)
                         if prefix.document_ids[j] == doc)
        spelling = ''.join(c for c in unicodedata.normalize('NFD', recent)
                           if not unicodedata.combining(c)).lower()
        letter = ''.join(c for c in unicodedata.normalize('NFD', token)
                         if not unicodedata.combining(c)).lower()
        if letter == 'ι' and spelling.endswith('τ'):
            value = (-4.3 if spelling.endswith('στ') else
                     -3.5 if spelling.endswith('ιτ') else -1.5)
        elif letter == 'υ' and spelling.endswith('στ'):
            value = -2.0
        elif spelling.endswith('τι'):
            if letter in {'σ', 'ς', 'μ'}:
                value = -3.0
            elif spelling.endswith('στι') and letter in {'ν', 'κ'}:
                value = -5.0 if letter == 'ν' else -2.7
    return None, value

programs.haiku:
"""Layer 1, MLP output component 2134 (down_proj), as a handful of readable rules.

The component is quiet almost everywhere (it fires on about 0.1% of tokens) and its
activation is signed. Its large values come from a few word contexts:

1. Right after a verb of beginning ('start', 'starts', 'started', 'starting', 'begin',
   'begins', 'began'), the next word decides the sign. 'to' is strongly negative (about -5.5:
   'started to'), and 'at', 'from', 'with' are negative too. 'by', 'out', 'off', 'over'
   are positive (about +4: 'start by', 'started out').
2. After 'most' or 'best': 'of' (+1.8), 'known' (+3.5) and 'often' (+2) are positive.
3. An escaped tab ('\\t' inside a Go or JSON-escaped code string) that continues an
   indented run, i.e. the second and later tabs, is positive (about +3.4).
4. Greek iota that completes a '-τι' ending, as in 'σπίτι', is negative (about -3).
5. An 'it' or 'im' piece that follows a word ending in 'st' or 'ст' (as in 'constit|ution',
   'best|imm', 'ст|ит'): negative (about -3), since these pieces spell 'stit'/'stim'.

Everything else predicts 0. Context is read from the previous token only (carry unused).
"""
READS = ()

START = {"start", "starts", "started", "starting", "begin", "begins", "began", "beginning"}
AFTER_START = {" to": -5.5, " at": -3.5, " from": -3.0, " with": -1.1,
               " by": 4.0, " out": 4.0, " off": 4.0, " over": 3.3}
AFTER_MOST_BEST = {" of": 1.8, " known": 3.5, " often": 2.0}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    if len(toks) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0  # first token of a document: no context
    prev = toks[-2]
    word = prev.strip().lower()
    if cur == "\\t" and prev in ("\\t", "t"):
        return None, 3.4  # a tab continuing an indented run
    if word in START:
        return None, AFTER_START.get(cur, 0.0)
    if word in ("most", "best"):
        return None, AFTER_MOST_BEST.get(cur, 0.0)
    if cur == "ι" and prev == "τ":
        return None, -3.0  # Greek '-τι' ending
    if not cur.startswith(" ") and word.endswith(("st", "ст")) and cur.lower()[:2] in ("it", "im", "ит", "им"):
        return None, -3.0  # 'stit' / 'stim' split across tokens
    return None, 0.0

programs.sol:
"""Approximate the component's context-initial pulse.

A row/document reset opens a pulse, which lasts through an identical-token
leading run. Its strength depends on the first token: English word class,
capitalization, word frequency and dictionary noun morphology.
After the leading run, the prediction is zero.
NUL and written-out whitespace escapes have particularly large pulses.
The category averages deliberately omit arbitrary per-token amplitudes.
"""
import regex
import wordnet
from wordfreq import zipf_frequency

READS = ()
ARTICLES = {'a', 'an', 'the'}
DEMONSTRATIVES = {'this', 'that', 'these', 'those'}
AUXILIARIES = {
    'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being',
    'do', 'does', 'did', 'have', 'has', 'had', 'can', 'could',
    'will', 'would', 'shall', 'should', 'may', 'might', 'must',
}
PREPOSITIONS = {
    'of', 'in', 'for', 'with', 'on', 'at', 'from', 'by', 'about', 'as',
    'into', 'over', 'after', 'under', 'between', 'through', 'before',
}
POSSESSIVES = {'my', 'our', 'your', 'his', 'her', 'its', 'their'}
CONJUNCTIONS = {'and', 'but', 'or', 'so', 'yet', 'nor', 'if', 'unless'}


def initial_value(text):
    if text == '\x00':
        return 36.45
    if text in {'\\n', '\\t'}:
        return 10.25
    if text == '<|im_start|>':
        return 2.8
    if text == '<|im_end|>':
        return 1.4
    if text == '<|endoftext|>':
        return -0.9
    if text == 'user':
        return 6.2
    if text == 'assistant':
        return 0.8
    word = text.strip()
    lower = word.lower()
    spaced = bool(text and text[0].isspace())
    if not word:
        return 0.4
    # Import and package declarations behave like structural text.
    if text in {'package', 'import', 'using', '#include'}:
        return 0.0
    if word.isdigit():
        return -0.1
    if word in {'I', 'We', 'You', 'Me'}:
        if not spaced:
            return 9.7
        return 2.2 if word == 'I' else 6.5
    if not spaced and word == 'They':
        return 8.1
    if not spaced and word in {'He', 'She', 'It'}:
        return 2.3
    if lower in POSSESSIVES:
        return 0.8
    if lower in ARTICLES | DEMONSTRATIVES:
        return -0.1
    if lower == 'there':
        return 5.5 if spaced else 11.5
    if lower == 'to':
        return 3.25 if spaced else 7.0
    if lower in AUXILIARIES | PREPOSITIONS | CONJUNCTIONS:
        return 0.8
    if lower in {'no', 'not', 'never'}:
        return 3.6
    letters = [c for c in word if c.isalpha()]
    if not letters:
        return -0.2
    if regex.search(r'\p{Script=Cyrillic}', word):
        return 2.4 if word[0].isupper() else 1.5
    latin = all(regex.fullmatch(r'\p{Script=Latin}', c) for c in letters)
    if not latin:
        return 0.0 if len(word) == 1 else 0.8
    # Coarse content-word averages; no learned token-ID lookup.
    pos = wordnet.parts_of_speech(lower)
    plural = lower.endswith('s') and any(
        b != lower for b in wordnet.base_forms(lower, 'noun')
    )
    if plural:
        return 3.9 if spaced else 6.0
    frequency = zipf_frequency(lower, 'en')
    if frequency > 6.7:
        return 0.8
    if 'adjective' in pos:
        return 0.8 if spaced else 2.0
    if word[0].isupper() and not spaced:
        return 5.2 if frequency > 5.2 else 3.5
    if spaced:
        return 1.4 if len(word) <= 3 else 2.3
    return 2.6


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = initial_value(prefix.token_strings[-1])
        return (doc, token, value, True), value
    _, first_token, value, repeating = carry
    repeating = repeating and token == first_token
    return (doc, first_token, value, repeating), value if repeating else 0.0

programs.haiku:
"""layers.1.mlp.down_proj:2135 -- fires only on the first token of a document.

What it does: this component's activation is zero everywhere except at the first
token of each document (the position right after a document boundary, or the first
token of a row). There, its value depends on which word or symbol that token is,
and on nothing before it, since no earlier context exists. The program therefore:

  * returns 0 at every position that is not the first token of a document;
  * at a document start, scores the token by a few word classes:
      - chat/special markers (<|...|>)            -> 2.7
      - subject pronouns (I, We, You, They, ...)  -> 8.0
      - adjectives (new, good, great, ...)        -> -1.0
      - articles, prepositions, conjunctions      -> 0.3
      - a single capital letter                   -> 3.8
      - a plural-looking word ending in "s"       -> 5.4
      - other capitalised words                   -> 3.0 (2.0 after a space)
      - other lowercase words                     -> 2.3 (1.7 after a space)
      - code, digits, punctuation                 -> 0.3
      - non-Latin script                          -> 0.7

Why: the values were fit to the component's measured activation at document starts
(a per-token table, which reproduces it exactly). Plural nouns and pronouns are high,
function words and adjectives low. The simple version gets about 0.46 variance
explained on the eval rows. A full per-token table would get close to 0.9 in-sample,
but it has no concept behind it, and the word lists here are the readable part.
"""

READS = ()
FUNCTION_WORDS = {"the", "a", "an", "this", "these", "those", "that", "and", "or", "but", "of", "in", "on", "at",
                  "for", "with", "by", "from", "to", "is", "are", "be", "as", "it", "its", "his", "has", "does", "yes", "us"}
PRONOUNS = {"I", "We", "You", "They", "There", "He", "She", "It", "What", "When", "How", "If", "People", "Person"}
ADJECTIVES = {"new", "good", "great", "best", "high", "amazing", "excellent", "different", "active", "fast",
              "certain", "former", "every", "enough", "fresh", "pure", "golden", "sharp", "specific", "appropriate"}

def step(carry, prefix, upstream):
    t = prefix.position
    doc_start = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not doc_start:
        return carry, 0.0
    s = prefix.token_strings[-1]
    w = s.strip()
    if s.startswith("<|"):
        v = 2.7
    elif w in PRONOUNS:
        v = 8.0
    elif w.isascii() and w.isalpha():
        if w.lower() in ADJECTIVES:
            v = -1.0
        elif w.lower() in FUNCTION_WORDS:
            v = 0.3
        elif len(w) == 1 and w.isupper():
            v = 3.8
        elif w.endswith("s") and len(w) > 3:
            v = 5.4
        elif w[0].isupper():
            v = 3.0 if not s.startswith(" ") else 2.0
        else:
            v = 2.3 if not s.startswith(" ") else 1.7
    elif w.isascii():
        v = 0.3
    else:
        v = 0.7
    return carry, float(v)

programs.sol:
"""A spelling-sensitive response centered on 'wear', not clothing in general.

Whole wear-verb tokens and their split-token completions respond strongly.
Fabric words and several other w-word families respond more weakly.  Some
w-led spelling fragments also respond, positively or negatively; these rules
are deliberately selective rather than a table of every observed fragment.
Chinese 穿 is detected even across UTF-8 splits.  All other cases get zero.
State consists only of the trailing word and two bytes, reset per document.
This approximation leaves many rarer token-specific effects unexplained.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', b'')
    _, previous, tail = carry
    token = prefix.token_strings[-1].lower()
    raw = prefix.token_bytes[-1]
    word = token.strip()
    value = 0.0

    if re.fullmatch(r'wear(?:s|ing)?', word):
        value = 7.3
    elif word == 'wore':
