"""Wear detector. Fires when the text so far ends in a form of the verb "wear" (wear, wears,
wearing, wore, worn, wearer), including when the word is split across tokens (e.g. "W" +
"ear", "w" + "earing"). Weaker for close relatives: wield, swear, woven, wool, weave, and
the Chinese 穿 ("to wear")."""

STRONG = {"wear": 7.0, "wears": 7.5, "wearing": 7.0, "wore": 8.0, "worn": 6.0, "wearer": 7.5}
WEAK = {"wield": 4.5, "wielding": 4.5, "wields": 4.5, "swear": 3.1, "swearing": 2.4,
        "woven": 3.2, "wool": 2.8, "weave": 2.3, "weaving": 2.3, "穿": 3.9}
KEYS = {**WEAK, **STRONG}
LONGEST = max(len(k) for k in KEYS)
READS = ()


def step(carry, prefix, upstream):
    new_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]
    recent = "" if carry is None or new_doc else carry
    recent = (recent + prefix.token_strings[-1]).lower()[-LONGEST:]
    value = 0.0
    for key, act in KEYS.items():
        if recent.endswith(key):
            value = max(value, act)
    return recent, value

