"""Approximate a local -in/-ine spelling feature, not the preposition 'in'.

Short syllables after b/d/p are positive; those after c/s/x/z are negative.
Biochemical endings and dictionary-recognized chemicals add negative signal.
The current unfinished word supplies the onset across token boundaries.
Most tokens return zero; lexical exceptions and small background activity
are deliberately not modeled.
"""
import re
import regex
import wordnet
from anyascii import anyascii
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
WORD = re.compile(r'[^\W\d_]+$')
SYLLABLE = re.compile(r'([a-z]?)([iy]n)([aeio]?s?)$')
# Weights for a bare syllable and one extended by a vowel.
ONSETS = (
    ('b', 3.8, 1.6),
    ('c', -5.7, -3.3),
    ('d', 1.9, 0.9),
    ('p', 1.8, 0.9),
    ('f', 0.8, 0.2),
    ('mn', -0.6, -0.6),
    ('ghklr', -0.35, -0.35),
    ('t', 0.25, 0.25),
)
STANDALONE_SYLLABLES = ('bin', 'bins', 'din', 'pin', 'pine', 'tin', 'sine')


@lru_cache(maxsize=8192)
def response(token, stem):
    if not token.isascii() and not regex.search(r'\p{Script=Cyrillic}', token):
        if len(token) == 1 and anyascii(token).lower() == 'bin':
            return 3.3
        if token == '氨基酸':  # amino acid
            return -2.4
        if token == '素' and stem.endswith(('酵', '毒')):  # enzyme/toxin
            return -2.8
        return 0.0
    s, before = anyascii(token).lower().strip(), anyascii(stem).lower()
    if re.fullmatch(r'vitamins?', s):
        return -3.7
    if s == 'insulin':
        return -4.0
    if re.fullmatch(r'(?:en)?zym(?:e|es)?', s):
        return -1.7 if s == 'enzymes' else -2.6
    if s == 'chrome' and token == token.strip():
        return -3.4
    if s == 'cytok':
        return -1.9
    if s in ('toxin', 'toxins', 'ase', 'ases'):
        return {'toxin': -2.6, 'toxins': -1.2, 'ase': -0.7, 'ases': -0.3}[s]
    if token == 'In':
        return 0.0
    if token.endswith('/bin'):
        return 1.8
    if s in ('e', 'yme', 'ymes') and (before + s).endswith(('zyme', 'zymes')):
        return -3.4
    if len(s) > 6:
        return 0.0
    separated = bool(token and not token[0].isalpha())
    bare = s.lstrip('/_.-')
    if separated:
        before = ''
        if bare not in STANDALONE_SYLLABLES:
            return 0.0
    # Distinct biochemical word-parts do not all behave like plain -in.
    for parts, value in (
        (('idine', 'idines'), 0.1),
        (('amin', 'amine', 'amines', 'argin', 'umin'), -1.1),
        (('ycin', 'icin', 'icine', 'illin', 'isin'), -4.6),
        (('cin', 'xin', 'zin'), -3.2),
        (('ulin', 'inine'), -2.6),
    ):
        if bare in parts:
            return value
    if not re.search(r'[iy]n', bare):
        return 0.0
    match = SYLLABLE.search(before + bare)
    if match is None or not match[1]:
        return 0.0
    onset, core, ending = match.groups()
    extended = bool(ending and ending != 's')
    value = 0.0
    for letters, short, long in ONSETS:
        if onset in letters:
            value = long if extended else short
    if onset in 'sxz':
        value = -3.8 if ending.startswith('e') else -2.2
    if onset == 'c' and core == 'yn':
        value = -3.3
    if onset == 'b' and ending.startswith('o'):
        value = 2.7
    if before.endswith('id') and bare in ('in', 'ins', 'ine'):
        value = -2.2
    if bare.startswith(('bin', 'pin', 'din', 'tin')):
        value *= 0.75
    if separated and bare in ('sine', 'pin'):
        value = -1.5 if bare == 'sine' else 0.5
    if bare not in ('in', 'yn') + STANDALONE_SYLLABLES:
        if zipf_frequency(bare, 'en') > 4.0:
            value *= 0.15
    if bare in ('ines', 'dyn'):
        value *= 0.5
    whole = before + bare
    amino = any(wordnet.is_a(whole[-n:], 'amino acid')
                for n in range(5, min(len(whole), 10) + 1))
    if amino:
        value -= 2.0
    elif value < 0 and wordnet.is_a(whole, 'substance'):
        value -= 1.4
    if onset in 'csxztp' and wordnet.is_a(whole, 'protein'):
        value -= 1.0
    if onset in 'csxztp' and wordnet.is_a(whole, 'hormone'):
        value -= 3.0
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    stem = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, stem)
    match = WORD.search(stem + token)
    word = match.group()[-48:] if match else ''
    return (doc, word), float(value)

"""Approximate a response to Romance d-prepositions and tool boundaries.

French/Romanian de and Italian di get the largest preposition response.
An apostrophe after isolated d also gets a large response. Language is
estimated from word-frequency tables: two preceding words for d, eight
for de/di. Capitals weaken the d response. No future text is used.
Shell cd and the end of a tool call form two separate positive cases.
The letters cd embedded within a word or number get a weaker response.
Initial alphabetic tokens receive a negative offset, stronger without a
leading space. A document-initial Title: header fires on its colon. Most
other tokens are near zero, with small negative values for ordinary
apostrophes, thought starts, and tool-response ends.
"""
import math
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'fr', 'it', 'ro', 'es', 'pt', 'de')


@lru_cache(maxsize=12000)
def frequencies(word):
    return tuple(max(2.0, min(6.0, zipf_frequency(word, lang)))
                 for lang in LANGUAGES)


def language_weights(text, nwords):
    words = re.findall(r'[^\W\d_]{2,}', text.lower())[-nwords:]
    scores = [0.0] * len(LANGUAGES)
    for age, word in enumerate(reversed(words)):
        for i, frequency in enumerate(frequencies(word)):
            scores[i] += 0.85 ** age * frequency
    peak = max(scores)
    weights = [math.exp((score - peak) / 0.5) for score in scores]
    total = sum(weights)
    return [weight / total for weight in weights]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous, recent = ('', b'') if first else carry[1:]
    value = -0.005
    spelling = token.strip()
    word_start = token[:1].isspace() or not previous[-1:].isalnum()
    if word_start and spelling.lower() in ('de', 'di', 'd'):
        text = recent.decode('utf-8', errors='ignore')
        en, fr, it, ro, es, pt, de = language_weights(
            text, 2 if spelling.lower() == 'd' else 8
        )
        if spelling.lower() == 'de':
            value = (0.15*en + 0.75*fr + 0.4*it + 0.7*ro
                     + 0.3*es + 0.25*pt + 0.05*de)
        elif spelling.lower() == 'di':
            value = 0.95*it - 0.1
        else:
            value = 0.02 + 1.1*fr + 0.55*it
            if spelling.isupper():
                value *= 0.5
    elif token in ("'", '’') and previous.strip().lower() == 'd':
        value = 0.98
    elif token in ("'", '’'):
        value = -0.08
    elif spelling == 'cd':
        command_boundary = (
            token[:1].isspace() or previous[-1:] in " \t\r\n\"'`;&|"
        )
        value = 0.53 if command_boundary else 0.15
    elif token == ':' and recent == b'Title':
        value = 3.8
    elif token == '</tool_call>':
        value = 0.90
    elif token == '</tool_response>':
        value = -0.14
    elif token == '<think>':
        value = -0.22
    if first:
        if spelling.isalpha():
            value = -0.13 if token.startswith(' ') else -0.40
        elif spelling.isdigit():
            value = 0.03
        elif token.isspace():
            value = 0.17 if token.startswith(' ') else -0.08
        else:
            value = -0.03
    return (doc, token, (recent + prefix.token_bytes[-1])[-256:]), value

