READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history = ''
    else:
        history = carry[1]
    token = prefix.token_strings[-1]
    value = 0.0
    word = token.strip()
    if not history:
        value = -0.14 if word.isalpha() and not word.isupper() else -0.06
        if token.startswith(' ') and not word.isalnum():
            value = -0.01
    if word.lower() == 'addition':
        value = 0.095 if re.search(r'\bin\s*$', history, re.I) else 0.32
    elif word.lower() == 'edition':
        value = 0.22 if token.startswith(' ') else 0.35
    elif len(word) >= 2 and set(word) == {'·'}:
        value = -0.66
    elif word == 'part' and re.search(r'\bfile is\s*$', history):
        value = 1.2
    if re.search(r'\bimport\s*$', history):
        if word == 'static':
            value = 1.05 if '\\n' in history else 1.29
        elif word == 'java':
            value = 0.19 if '\\n' in history else 0.26
    history = (history + token)[-100:]
    return (doc, history), value

"""Predict numeric decimal points and C-style source/command boundaries.

The strongest responses are dots after short numbers, indented control
keywords, tab-plus-space indentation, and command-option dashes. Ordinary
prose stays close to zero; doubled middle dots get a negative response.
Recent decimal notation reinforces numeric dots, while list markers and
later version/IP separators are suppressed. State resets for each document.
"""
import re

READS = ()
CURRENCY_SIGNS = frozenset("$€£¥₹")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, previous = '', ''
    else:
        text, previous = carry[1:]
    s = prefix.token_strings[-1]
    line = text.rsplit('\n', 1)[-1]
    value = 0.0

    if s == '.' and text and text[-1] in '0123456789':
        number = re.search(r'[0-9]+$', text).group()
        before = text[:-len(number)]
        recent_decimal = bool(re.search(r'[0-9]\.[0-9]', before[-150:]))
        numbered_line = bool(re.fullmatch(r'\s*[0-9]+', line))
        if before.endswith('.'):
            value = 0.0  # Later separators in a version or an IP address.
        elif numbered_line and text != number:
            value = 0.35 if recent_decimal else -0.03
        elif (before.endswith('(') or before[-1:] in CURRENCY_SIGNS
              or re.search(r'\b[vV]$', before)):
            value = 1.05
        elif recent_decimal:
            value = 1.0 if len(number) == 1 else 0.73
        elif int(number) >= 1000:
            value = 0.04
        elif int(number) == 0:
            value = 0.85
        elif int(number) == 1:
            value = 0.78 if before.endswith('_') else 0.60
        else:
            value = 0.38

    word = s.strip(' \t')
    if word in ('if', 'for'):
        indented = re.fullmatch(r'\s*(?:[0-9]+\s+)?', line)
        escaped_indent = bool(re.search(r'\\[nt](?:\\t| )*$', text))
        starts_clause = (indented or previous.isspace() or escaped_indent
                         or line.rstrip().endswith('else'))
        if starts_clause:
            if ';' in text:
                value = 1.05 if word == 'if' else 0.85
            elif '{' in text or '}' in text or '\t' in s:
                value = 0.65 if word == 'if' else 0.45
            else:
                value = 0.20 if word == 'if' else 0.12
            if text.count(':') >= 3:
                value *= 0.8

    if s and not s.strip(' \t') and '\t' in s:
        spaces = s.count(' ')
        if spaces >= 5:
            value = 0.53 if spaces < 13 else 0.83
        elif s.count('\t') >= 2 and re.fullmatch(r'\s*[0-9]+', line):
            value = 0.5
        elif spaces == 3:
            value = 0.08

    if s and not s.strip(' ') and len(s) >= 13:
        if re.fullmatch(r'\s*[0-9]+\t[ \t]*', line):
            value = 1.15 if len(s) >= 30 else 0.8

    if s in (' -', ' --'):
        commands = (
            r'\b(?:git|grep|rg|cat|sed|find|cargo|npm|npx|pip|python|'
            r'pytest|docker|curl|wget|ls|head|tail|diff|rustc|go|ffmpeg|'
            r'rm|cp|mv|wc|awk|sort|tar|apt|make|bash|sh)\b'
        )
        if re.search(commands + r'\s*$', line):
            value = 1.4
        elif re.search(commands, line) and len(line) < 160:
            shell_syntax = re.search(r'&&|\||`|/workspace|/testbed', line)
            value = 0.9 if shell_syntax else 0.4

    if s == '\u00b7\u00b7':
        value = -1.16
    return (doc, (text + s)[-500:], s), value

