"""Predict some strongly bound, two-part names and expressions.

Large positive responses occur inside reserved underscore identifiers, US
state-name endings followed by 'State', C types, and Microsoft product names.
A few common compound nouns have signed responses too. Unrecognized text
gets zero; this is a deliberately partial account of the component.
"""
import re
import pycountry

READS = ()
US_STATE_ENDINGS = {s.name.lower().split()[-1] for s in pycountry.subdivisions
          if s.country_code == 'US' and s.type == 'State'}


def compound(previous, token):
    """Recognize lexical constructions, using their words, not token IDs."""
    word = token.strip()
    p, w = previous.lower(), word.lower()
    if w == 'state' and p in US_STATE_ENDINGS:
        return 2.7 if word == 'State' else 1.4
    if p == 'long' and w == 'long':
        return 4.3
    if p == 'unsigned' and w in {'long', 'int'}:
        return 2.6 if w == 'long' else 1.2
    if p == 'int' and word == 'main':
        return 0.9
    if p == 'asm' and w == 'volatile':
        return 4.1
    if p == 'roman' and w.startswith('numer'):
        return 2.3
    if p == 'windows':
        if w in {'live', 'phone'}:
            return 6.0
        if w in {'media', 'movie', 'azure'}:
            return 4.0
        if w in {'mobile', 'forms', 'nt'}:
            return 2.8
    if p == 'primary' and w == 'key':
        return 1.7
    if p == 'time' and w == 'complexity':
        return 2.5
    if p in {'main', 'key', 'abstract', 'general', 'big'} and w in {'idea', 'ideas'}:
        return 2.0
    if p == 'financial' and w in {'statements', 'reporting', 'aid'}:
        return 1.2
    if p in {'football', 'hockey', 'basketball', 'soccer'} and w == 'player':
        return 0.85
    if p == 'sports' and w == 'team':
        return -0.33
    if p in {'big', 'major', 'capital'} and w in {'city', 'cities'}:
        return -2.7
    if p == 'general' and w == 'public':
        return -1.7
    if p in {'international', 'european', 'economic'} and w == 'community':
        return -2.2
    if p in {'federal', 'central'} and w in {'government', 'governments'}:
        return -1.25
    if (p == 'economic' and w in {'growth', 'development'} or
            p == 'population' and w == 'growth'):
        return -1.3
    if p == 'programming' and w in {'language', 'languages'}:
        return -0.85
    if p == 'python' and w == 'interpreter':
        return -0.48
    if word == 'TV' and p in {'apple', 'android'}:
        return 1.5
    if p == 'york' and word == 'City':
        return 0.95
    if p == 'grand' and word == 'Central':
        return 1.4
    if p == 'view' and word == 'Answer':
        return 3.8
    if p == 'final' and word == 'Answer':
        return 1.5
