        # Reserved identifiers differ from a bare separator inside a name.
        value = 0.3 if len(text) > 2 and text[-3].isalnum() else 0.8
        if word in {'func', 'import', 'VA'}:
            value = 6.0
        elif word in {'builtin', 'built', 'force', 'LINE'}:
            value = 4.1
        elif word in {'py', 'Py'}:
            value = 3.5
        elif word in {'test', 'tests'}:
            value = 2.0
        elif word == 'internal':
            value = 3.3
        elif word in {'init', 'repr', 'str', 'eq', 'len', 'iter', 'all', 'doc',
                      'construct', 'class'}:
            value = 0.0
        elif word == 'name':
            value = 1.2
        elif word == 'main':
            value = 0.5
        elif word == 'version':
            value = 0.5
