    if token == '-local' and previous == 'datetime':
        value = 3.5
    if text.endswith('System') and token == '.Collections':
        value = -1.05
    if text.endswith('.Collections') and token == '.Generic':
        value = 1.6
    return (doc, (text + token)[-50:]), value

