    if tok in WEB_CODE_FRAGMENTS:
        return None, VALUES["web"]
    return None, 0.0

programs.sol:
"""Approximate a binding/value-introducer feature from visible syntax.

A strong positive response marks a spaced equals after a variable-like name,
particularly a bare name on an indented line or a declared variable. Equations,
member assignments and indexed targets receive smaller responses. Related
signals mark assignment arrows, map-key colons and iterator bindings.
A line-initial indented equals is a negative formatting signal.
The last 70 tokens supply bounded context, reset at document boundaries.
This deliberately leaves most ordinary text and token-specific variation at zero.
"""
from collections import deque
import re

READS = ()


def binding_context(previous):
    text = ''.join(previous).replace('\\t', '\t')
    line = re.split(r'\n|\\n', text)[-1]
    # Ignore Markdown code ticks and line-number gutters in code listings.
    line = re.sub(r'^\s*\d+\t', '', line.replace('`', ''))
    match = re.search(r'[A-Za-z_$][A-Za-z_0-9$]*$', text)
    name = match.group() if match else ''
    bare = bool(re.fullmatch(r'\s*[A-Za-z_$][\w$]*\s*', line))
    indented = bool(line) and line[0].isspace()
    code = any(c in text[-180:] for c in '{};_')
    declared = bool(re.search(
        r'\b(?:var|let|const|int|float|double|long|char|String|static|final|bool|auto)'
        r'\s+(?:mut\s+)?[*&]*[A-Za-z_$][\w$]*'
        r'(?:\s*:\s*[\w<>\[\]]+)?$', line))
    declared = declared or ((indented or code) and bool(re.fullmatch(
        r'\s*[A-Z]\w*(?:<[^=;{}]+>)?(?:\[\])?\s+[a-z_$]\w*', line)))
    math = any(c in line for c in '+-*/^\\')
    return name, bare, declared, indented, code, math, line


def predict(s, previous):
    op = s.strip()
    if s in (' =', '=', ' :=', ':'):
        name, bare, declared, indented, code, math, line = binding_context(previous)
        last = previous[-1].strip() if previous else ''
        if s == ':':
            if not indented or not code:
                return 0.03
            if bare:
                return 0.66
            return 0.06 if math else 0.33
        if s == ' :=':
            if bare:
                return 4.6
            return 3.3 if any(c.islower() for c in name) else 1.5
        if s == ' =' and line and not line.strip():
            return -2.4 if len(line) <= 5 else -0.6
        if s == ' =' and re.fullmatch(
                r'\s*[A-Za-z_$]\w*(?:\s*,\s*[A-Za-z_$]\w*)+\s*', line):
            return 3.2
        # Equals: distinguish a binding target from an expression's ending.
        if not name:
            return 0.39 if last.endswith(']') else 0.0
        if len(name) <= 2:
            if not bare:
                return 1.55 if declared else 0.45
            if not s.startswith(' '):
                return 0.87
            if indented:
                return 3.6
            return 3.1 if code else 1.8
        if bare:
            if s == '=':
                return 1.3
            return 2.5 if any(c.isupper() for c in name) else 3.7
        if declared:
            return 3.2 if s.startswith(' ') else 1.3
        return 1.46 if s.startswith(' ') else 0.26
    if op == '<-':
        last = previous[-1].strip() if previous else ''
        return 5.2 if last and (last[-1].isalnum() or last[-1] == '_') else 2.0
    if op in ('==', '==='):
        return 0.58 if s.startswith(' ') or op == '==' else 0.08
    if op == '=>':
        return 0.92 if s.startswith(' ') else 0.49
    if op in ('+=', '-='):
        return 0.58
    if op.endswith(':') and op[:-1].strip('\\') in ('"', "'"):
        return 0.95 if '"' in op else 0.78
    if s.startswith('=') and len(s) > 1 and s[1] != '=':
        # Equals fused with the beginning of its right-hand side.
        rhs = s[1:]
        if rhs.startswith('$'):
            last = previous[-1].rstrip() if previous else ''
            return 1.9 if last and (last[-1].isalnum() or last[-1] == '_') else 0.0
        if rhs[0].isalpha():
            return 0.8 if len(rhs) > 1 else 0.45
        if rhs[0] in "([\"'":
            return 0.45
    if s in (' in', 'in'):
        text = ''.join(previous).replace('\\n', '\n').replace('\\t', '\t')
        # Iterator binding, not the ordinary English preposition.
        loop = re.search(r'\b(?:for|foreach)\b\s*\(?\s*(?:(?:int|var)\s+)?'
                         r'[A-Za-z_]\w*(?:\s*,\s*[A-Za-z_]\w*)*\s*$', text)
        if loop:
            lead = text[:loop.start()].rsplit('\n', 1)[-1]
            if not lead.strip() or '[' in lead or '(' in lead:
                return 1.05
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = deque(maxlen=70)
    else:
        previous = carry[1]
    value = predict(prefix.token_strings[-1], previous)
    previous.append(prefix.token_strings[-1])
    return (doc, previous), float(value)

"""Approximate opening-syntax responses and the contrast of Han with ASCII.

Document-initial declaration keywords are positive; comment/HTML openers and
an initial end marker are negative. Han-containing tokens get positive
baselines. For ASCII letters and numerals, two decaying Han proportions
represent a few-token context and a roughly ten-token context. Zero and one
have stronger numeric contrast; leading whitespace weakens the letter effect.
Other token-specific variation remains unexplained.
"""
import regex

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
OPENING_DECLARATIONS = {
    'class': 1.99,
    'import': 0.955,
    'const': 1.12,
    'package': 0.50,
    'using': 0.38,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    w = s.strip()
    first = carry is None or carry[0] != doc
    short, long = (0., 0.) if first else carry[1:]
    han = bool(HAN.search(s))
    value = 0.0
    if first:
        if s in OPENING_DECLARATIONS:
            value = OPENING_DECLARATIONS[s]
        elif s == '//\n':
            value = -4.34
        elif s == '//':
            value = -0.432
        elif s == '<!':
            value = -2.58
        elif s == '<|endoftext|>':
            value = -2.10
        elif han:
            value = 0.11 if len(w) == 1 else 0.34
    elif han:
        value = 0.025 if len(w) == 1 else 0.005
    elif w.isascii() and w.isdigit():
        if w in ('0', '1'):
            value = -0.003 + 0.19*short - 0.32*long
        else:
            value = -0.001 + 0.15*short - 0.21*long
    elif w.isascii() and w.isalpha():
        if s[0].isspace():
            value = 0.001 - 0.058*short - 0.095*long
        else:
            value = -0.003 - 0.205*long
    return (doc, 0.5*short + 0.5*han, 0.9*long + 0.1*han), value

"""Expression-introducing code words, especially returns and early exits.

Indentation and statement delimiters distinguish these words from ordinary prose.
Returns are stronger near a conditional and with tab indentation. Binding words,
exception/yield statements, type tests, and conditional-expression operators also
receive positive predictions. Escaped newlines in quoted source count as line breaks too.
This is a lexical approximation, not a parser; other tokens are left near zero.
"""
import re

READS = ()

STATEMENTS = {
    'var': .92, 'let': .90, 'const': 1.02,
    'break': 1.15, 'continue': 1.15, 'throw': 1.15,
    'raise': 1.15, 'yield': 1.40, 'assert': .40,
    'with': .85, 'match': .65, 'case': .35,
}
MODIFIERS = {'static', 'public', 'private', 'protected', 'export',
             'extern', 'inline', 'pub', 'volatile'}
CHECKS = {'isinstance': .56, 'hasattr': .57, 'enumerate': .33}
STRINGS = re.compile(r'''"(?:\\.|[^"\\])*"?|'(?:\\.|[^'\\])*'? ''', re.X)


def predict(token, past):
    word = token.strip()
    opening = word.startswith('(')
    if opening:
        word = word[1:]
    interesting = (word in STATEMENTS or word in CHECKS or word in
                   {'return', 'mut', 'typeof', 'await', 'async', 'final',
                    'readonly', 'typename', '||', '??', '&&', '?', ':'})
    if not interesting:
        return 0.0

    past = past.replace('\\n', '\n').replace('\\t', '\t').replace('\\r', '\r')
    line = past.rsplit('\n', 1)[-1]
    start = bool(re.fullmatch(r'[ \t]*(?:\d+[ \t]*)?(?:[+-][ \t]*)?', line))
    gap = bool(past and past[-1].isspace())
    previous = past.rstrip()
    char = previous[-1:] if previous else ''
    leading = bool(token and token[0].isspace())
    words = re.findall(r'[A-Za-z_]+', previous[-100:])
    last_word = words[-1] if words else ''
    conditional = bool(re.search(r'\b(if|catch|except)\b', past[-120:]))
    code = bool(re.search(r'[=;{}]|\b(return|const|let|var|if)\b', line))

    if word in {'||', '??', '&&', '?', ':'}:
        if word == ':':
            if '\n' in token or '\r' in token:
                return 0.0
            clean = STRINGS.sub("''", line)
            questions = list(re.finditer(r'(?<!\?)\?(?![?.])', clean))
            ternary = questions and questions[-1].start() > max(
                clean.rfind(':'), clean.rfind(';'))
            return (1.4 if leading else .8) if ternary and code else 0.0
        if word == '?':
            return .95 if leading and code else 0.0
        if word == '&&':
            return .16 if code else 0.0
        return ({'||': .55, '??': .75}[word]) if code else 0.0

    if char == '@' and word in {'return', 'var'}:
        return -.17
    if not gap and char in {'.', '_', '@', '\\'}:
        return 0.0
    if not leading and not opening and not gap and char.isalnum():
        return 0.0

    if word in CHECKS:
        return CHECKS[word]
    if word == 'typeof':
        return 1.9 if char == '(' or previous.endswith('&&') else 1.2
    if word == 'async':
        return .85
    if word == 'await':
        allowed = start or gap or char in {'=', '(', ':'} or last_word == 'return'
        return 1.5 if allowed else 0.0
    if word == 'mut':
        allowed = char == '&' or last_word == 'let' or opening
        return (0.8 if opening else 1.2) if allowed else 0.0
    if word in {'final', 'readonly', 'typename'}:
        allowed = last_word in MODIFIERS or (code and char == ',')
        allowed |= start and leading
        return 1.0 if allowed else 0.0

    statement = start or gap or char in {';', '{', '}', ':'}
    if word in {'return', 'break', 'continue', 'throw'}:
        statement |= char == ')' or last_word in {'else', 'then'}
        statement |= previous.endswith('*/')
    if word in {'var', 'let', 'const'}:
        statement = statement or char == '(' or opening
        if word == 'const':
            if last_word in MODIFIERS:
                return .85
            if char == ',':
                return .55
    if not statement:
        return 0.0
    if word == 'return':
        value = 1.5 + .45 * conditional
        value += .25 * (token.startswith('\t') or '\t' in line)
        value += .2 * (char == ')' and not start)
        if char == '{' and not start and not gap:
            value *= .85
        return value
    if word in {'with', 'match'} and not leading:
        return 0.0
    value = STATEMENTS.get(word, 0.0)
    if word == 'throw' and conditional:
        value += .35
    if word == 'const' and not leading:
        value *= .75
    if opening:
        value *= .65
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    past = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = predict(token, past)
    return (document, (past + token)[-256:]), value

"""Approximate a sparse formatting and multilingual lexical feature.

Positive pulses mark commas after standalone dates or numerical lists, and the
minus sign opening a unified-diff range. Dates embedded in prose respond less.
Smaller rules recognize translations of 'in', isolated nasal-vowel characters,
and the colon in a document-initial 'Title:' field. Other tokens get zero;
irregular initial-token effects and many weak lexical responses are omitted.
"""
import calendar
import re
import unicodedata
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
MONTH = '(?:' + '|'.join(
    list(calendar.month_name)[1:] + list(calendar.month_abbr)[1:]
) + ')'
MONTH_DAY = re.compile(MONTH + r'\.?\s+\d{1,2}(?:st|nd|rd|th)?$', re.I)
DAY_MONTH_YEAR = re.compile(r'\d{1,2}\s+' + MONTH + r'\.?\s+\d{4}$', re.I)
DATE_PREPOSITION = re.compile(
    r'\b(on|in|from|until|since|through|after|before|to|of|for|by|between|'
    r'dated|effective)\s*$', re.I
)

@lru_cache(maxsize=20000)
def frequency(word, language):
    return zipf_frequency(word, language)


def language_of(text, languages):
    """Choose the dictionary in which recent words are most frequent."""
    words = re.findall(r'[^\W\d_]+', text.lower())[-12:]
    return max(languages, key=lambda lang: sum(
        max(0, frequency(w, lang) - 2) for w in words if len(w) > 1
    ))


def response(text, token):
    if token == ' -' and text.rstrip().endswith('@@'):
        return 1.75
    if token == ':' and text.strip() == 'Title':
        return 4.48
    if token == ',':
        date = MONTH_DAY.search(text) or DAY_MONTH_YEAR.search(text)
        if date:
            lead = text[:date.start()]
            if DATE_PREPOSITION.search(lead):
                return 0.15
            return 1.0 if len(lead.split('\n')[-1].split()) <= 3 else 0.6
        if re.search(r'\d(?:st|nd|rd|th)$', text):
            return 0.3
        number = re.search(r'\d+$', text)
        if number:
            if re.search(r'@@[^\n]*$', text):
                return 0.35
            before = text[:number.start()]
            if before.endswith('['):
                return 0.4
            if not before.split('\n')[-1].strip():
                return 0.55
            if before[-1:].isspace():
                previous = before.rstrip()[-1:]
                if previous == ',':
                    return 0.3
                if previous.isalpha() or previous in '([':
                    return 0.03
                return 0.2
            return 0.0
        return -0.005
    if token in ('0', '1') and MONTH_DAY.search(text + token):
        if re.search(r'3[01]$', text + token):
            return 0.7  # Completing day 30 or 31 of a month.
    letters = unicodedata.normalize('NFD', token.strip())
    if (len(letters) == 2 and letters[0].lower() in 'aeiou'
            and letters[1] == '\N{COMBINING TILDE}'):
        return 1.0
    word = token.strip().lower()
    boundary = token[:1].isspace() or not text or not text[-1].isalpha()
    if boundary and word == 'en':
        lang = language_of(text, ('en', 'es', 'fr', 'nl', 'sv', 'da', 'nb'))
        return 0.55 if lang == 'es' else 0.0
    if boundary and word == 'em':
        return 0.6 if language_of(text, ('en', 'pt', 'vi', 'fr')) == 'pt' else 0.03
    if boundary and word == 'в':
        return 0.2
    if boundary and word == 'w':
        return 0.35 if language_of(text, ('en', 'pl', 'de')) == 'pl' else 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = response(text, token)
    return (doc, (text + token)[-200:]), value

programs.haiku:
"""Layer-1 MLP down_proj component 2153: a sparse detector for "a number is coming next".

Mostly silent. It fires, positively, on a few kinds of token where the next token is very likely a number:
  * a comma closing a month-and-day date ("Sep 17," -> year). Strongest when the date stands alone at the start of a line (a dateline or timestamp); weak after a prose preposition ("On June 10,");
  * a comma right after a digit in a citation or number list ("[15," -> "16", "7, 17, 29,"), weak;
  * a " -" right after "@@" in a diff hunk header ("@@ -12,7 +12,8 @@"), the strongest;
  * the preposition "en"/"em"/"в" in in-language prose (Spanish, Portuguese, Russian), weak.
Everything else predicts 0; the component's activation there is small, unstructured noise.
"""
import re

READS = ()

MONTH_DAY_COMMA = re.compile(r"(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.? ?\d{0,2}\s?\d(st|nd|rd|th)?$")
LINE_START = re.compile(r"(^|\n)\s*(\d+\.\s*)?$")
PROSE_BEFORE = re.compile(r"\b(On|on|In|in|of|between|from|until|since|to|and)\s+$")
DIGIT_BEFORE = re.compile(r"\d$")
PREPOSITIONS = {" en", " em", " в", " В"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    recent = "".join(prefix.token_strings[-14:-1])  # the tokens before this one
    if tok == ",":
        m = MONTH_DAY_COMMA.search(recent.rstrip())
        if m:
            head = recent.rstrip()[: m.start()]
            if LINE_START.search(head):
                return None, 1.2
            if PROSE_BEFORE.search(head):
                return None, 0.2
            return None, 0.7
        if DIGIT_BEFORE.search(recent):
            return None, 0.10
    if tok == " -" and recent.endswith("@@"):
        return None, 1.8
    if tok in PREPOSITIONS:
        return None, 0.2
    return None, 0.0

