"""Recognize a small mixture of phrase endings and document/code prologues.

'Wide variety' and idioms about being 'in shape' get positive pulses.
Title punctuation, Python-3 markers, and several code prologues
get negative pulses. Prologue pulses are weaker inside an existing document.
A small first-token baseline, decorative punctuation, and initial carriage
returns cover other regularities. Unrecognized interior text gets zero. This
does not attempt to reproduce the component's diffuse, small background values.
"""
import re

READS = ()

# Familiar English fixed expressions: final word -> preceding words, pulse.
EXPRESSIONS = {
    'variety': ('wide', 2.7),
    'thereof': ('lack', 1.2),
    'reference': ('future', 1.4),
    'further': ('without', 0.5),
    'doubt': ('without', 1.3),
    'tear': ('wear and', 0.65),
    'later': ('sooner or', 0.6),
    'part': ('in', 0.15),
    'down': ('broken', 0.65),
}


# Source-file/document opening markers.
OPENERS = {
    '//\n': 3.32,
    '"""\n': 2.08,
    "'''\n": 1.42,
    '<!': -3.26,
    '**': 1.58,
    'Title': 0.87,
    'def': 1.29,
    '#!/': 0.74,
}


def ends(text, phrase):
    return text == phrase or text.endswith(' ' + phrase)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, age = '', 0
    else:
        _, text, age = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    before = text.rstrip()
    lower = before.lower()
    value = 0.0

    if age == 0:
        cased_word = word.isalpha() and (word.islower() or word.istitle())
        value = OPENERS.get(token, 0.27 if cased_word else 0.12)
    if word in EXPRESSIONS:
        preceding, pulse = EXPRESSIONS[word]
        if ends(lower, preceding):
            value = pulse
    if word == 'part' and ends(lower, 'at least in'):
        value = 0.65
    if word == 'shape':
        value = 0.05
        if ends(lower, 'out of'):
            value = 5.2
        elif re.search(r'\b(better|good|nice)$', lower):
            value = 4.9
        elif re.search(r'\b(great|top|worse)$', lower):
            value = 3.8
        elif ends(lower, 'in'):
            value = 1.6
            if re.search(r'\b(stay|staying|keep|keeps|keeping)\b',
                         lower[-50:]):
                value = 3.2
        elif ends(lower, 'in one'):
            value = 2.5
        elif re.search(r'\b(face|odd|body|took|taking)$', lower):
            value = 0.8

    # Document labels and repository-issue markup.
    if token == ':' and before == 'Title':
        value = -8.88
    if word == 'issue' and before.endswith('<issue_start><'):
        value = -13.4
    # The Python-3 marker, especially in interpreter/library paths.
    if word == '3' and lower.endswith('python'):
        if lower.endswith('/bin/python'):
            value = -10.0
        elif lower.endswith('/python'):
            value = -3.5
        elif text.startswith('#!') and age < 10:
            value = -5.4
        else:
            value = -0.2
    # Literal file prologues are stronger than examples quoted in prose.
    prologue = text.startswith('#!') and age < 10
    if token == '/env' and before.endswith('#!/usr/bin'):
        value = -2.69 if prologue else -0.9
    if token in ('/bash', '/sh') and before.endswith('#!/bin'):
        pulse = -2.48 if token == '/bash' else -1.15
        value = pulse if prologue else -0.4
    if token == ' bash' and before.endswith('#!/usr/bin/env'):
        value = -3.0 if prologue else -0.6
    if word == 'once' and before.endswith('#pragma'):
        value = -1.5 if age < 8 else -0.2
    if word == 'strict' and before.endswith(('"use', "'use")):
        value = -0.75 if age < 8 else -0.3
    if token == '.Generic' and before.endswith('using System.Collections'):
        value = -2.2 if age < 20 else -1.5
    if token == '_literals' and before.endswith('__future__ import unicode'):
        value = -3.0 if age < 40 else -1.5
    if (word in ('models', 'render')
            and re.search(r'from django\.[\w.]+ import$', before)):
        value = -5.0 if word == 'models' else -3.5
    if token == '\\Response' and before.endswith('\\Illuminate\\Http'):
        value = -3.2
    if token == '\\Controllers' and before.endswith('namespace App\\Http'):
        value = -1.3
    # Code-golf and probability-problem boilerplate.
    if word == 'online' and before.endswith('Try it'):
        value = -3.3
    if word == 'from' and before.endswith('without replacement'):
        value = -3.4
    if word == 'picking' and before.endswith('prob of'):
        value = -1.85

    # Decorative middle dots, colon-art banners, and blank CR prologues.
    if token == '··':
        value = -0.99
    if len(word) >= 6 and set(word) == {':'} and '/*' in text:
        value = -9.4
    if token == '\r' and not text.strip('\r'):
        value = 2.92
    if token == '<|endoftext|>':
        text, age = '', 0
    else:
        text, age = (text + token)[-160:], age + 1
    return (doc, text, age), float(value)

programs.haiku:
"""Layer 1, MLP down_proj, component 2154: a sparse feature.

Mostly near zero. It is large in a few word contexts:
  * negative on the version digit of an interpreter path ("/usr/bin/python3"),
    on "Title:" at the start of a document, on "replacement from",
    on shell/interpreter names in paths ("/bin/env", "/bin/bash") and on
    ".Generic" in "System.Collections.Generic";
  * positive on "shape" in the sense of fitness ("in shape", "good shape"),
    on "variety" after "wide", on "//" starting a new document, and on the
    carriage return "\\r" (Windows line ends);
  * a small positive offset on the first token of each document.
"""
READS = ()

SHELL_NAMES = {"/env", "/bash", "/sh", "/zsh"}
FITNESS_ADJ = {" good", " great", " bad", " better", " worse", " best",
               " physical", " nice", " top", " prime", " enough"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings
    cur = tok[-1]
    prev = tok[-2] if len(tok) > 1 else ""
    if len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.22  # first token of a document
    if cur == "3" and prev == "/python":
        return carry, -3.4  # python3 in a path
    if cur == ":" and prev == "Title":
        return carry, -3.5
