"""A partial code-lexicon explanation: negative library/type references,
positive assigned booleans. Training examples repeatedly showed strong
negative imports (especially typing and copy), container type names,
C++ headers/scope, and override annotations. Boolean values following
'=' or ':' had positive responses, unlike most other uses of these words.

Keep only a short document-local text tail to recognize these contexts.
Rare name fragments, metadata and separator responses are not modeled.
"""
import re
import sys

READS = ()
COLLECTIONS = set(
    'List Set Map Dict Array Collection ArrayList HashMap HashSet '
    'Mapping Sequence MutableMapping'.split()
)
HINTS = set(
    'Any Optional Union Generic Callable Tuple Iterable Iterator TypeVar'.split()
)
BASE_TYPES = set(
    'Object Exception System Enum Integer String Long Vector Math'.split()
)
HEADERS = set(
    'string vector list map set queue stack deque algorithm cmath math time'.split()
)


def response(token, tail):
    text = token.strip()
    word = text.lstrip('.<([=:')
    before = tail + token[:len(token) - len(token.lstrip())]
    imported = bool(re.search(
        r'(?:^|[;\n"\'])\s*(?:\d+\s*[:|]?\s*)?#?'
        r'(?:(?:import|using)\s+[\w., ]*|'
        r'from\s+[\w.]*(?:\s+import\s+[\w., (]*)?)$', before
    ))
    joined = token[:1].isalpha() and tail[-1:].isalnum()

    if text == 'import' and re.search(r'\btyping\s*$', tail):
        return -3.93
    if imported:
        if word == 'typing':
            return -12.36
        if word == 'copy':
            return -7.37
        if word in {'math', 'cmath'}:
            return -4.31
        if word in sys.stdlib_module_names and word not in {'from', 'as'}:
            return -1.47
    if word in HEADERS and re.search(r'#\s*include\s*[<"][^>"\n]*$', tail):
        return -3.52

    if not joined and (word in COLLECTIONS or word in HINTS):
        if word == 'Generic' and text.startswith('.'):
            return -5.37
        if imported:
            if word == 'List':
                return -5.28
            return -2.47 if word in HINTS else -3.17
        if text.startswith('.'):
            return -0.2
        if word == 'List':
            return -1.49
        return -0.06 if word in HINTS else -0.7
    if not joined and word in BASE_TYPES:
        if imported:
            return -1.62
        return -0.78 if word in {'Object', 'Exception'} else -0.15
    if imported and text.startswith('.') and word.isidentifier():
        system = re.search(r'(?:java|javax|android|System)\.', tail)
        return -0.85 if system else -0.2
    if imported and text == 'as':
        return -0.99
    if imported and re.search(r'\bas\s*$', tail) and word.isidentifier():
        return -0.47
    if imported and word == 'deepcopy':
        return -3.33

    if text in {'using', 'namespace', 'package'}:
        if not token[0].isspace() or re.search(r'(?:^|[;\n])\s*$', tail):
            return -0.65
    if text == '::':
        return -1.44 if tail.endswith('std') else 0.07
    if text in {'Override', '@Override', 'override'}:
        return -0.97

    literal = text.lstrip('=')
    if literal.lower() in {'true', 'false'}:
        spaced = token[:1].isspace() or text.startswith('=')
        if spaced and (text.startswith('=') or re.search(r'=\s*$', tail)):
            return 1.09
        if spaced and re.search(r':\s*$', tail):
            return 0.79
        if re.search(r'[(,]\s*$', tail):
            return 0.2
        if spaced and re.search(r'(?:return|while)\s*$', tail):
            return 0.3
        return -0.03 if spaced else 0.08
    if text in {'.random', '.Random'}:
        return -2.4
    if word == 'random' and re.search(r'=\s*$', tail):
        return -2.4
    if text in {'see', 'See'} and tail.rstrip().endswith('@'):
        return 2.05
    return 0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = response(token, tail)
    tail = (tail + token).replace('\\n', '\n')[-180:]
    return (doc, tail), value

