"""layers.1.mlp.down_proj:2155 -- a sparse "library type name in code" detector.

What it responds to. The component is quiet almost everywhere. It goes negative on the
names of libraries and types in source code:
  * `typing` in `from typing import ...` (strongest, about -10);
  * type names such as List, Set, Map, Dict, Optional, Object, Any, Exception when they
    are used as types or imported (about -2.5 in declarations, annotations, generics and
    import lists; near 0 in plain English prose and after a dot, as in `typing.List`);
  * well-known module and package names inside import lines (util, math, junit, Assert, ...),
    about -1.5;
  * `std` in `std::` (about -1.3), C++ standard headers after `#include <` (about -3),
    and `@Override` (about -1.2).
It is mildly positive on the boolean literals true/false (+0.4), and on the first `:`
of a document-opening `Title:` label that follows an end-of-text token (+4.4, rare).

What it is not. Most of its variance lies in small, idiosyncratic values that no short
rule captures, so this program explains only the large tails; it predicts 0 elsewhere.
"""
import re

READS = ()

# Type names that are library types when they appear in code.
TYPE_NAMES = {"List", "Set", "Map", "Dict", "Optional", "Collection", "Mapping", "ArrayList",
              "HashMap", "Object", "Exception", "Generic", "Any"}
# Module and package names that matter when they appear in an import line.
MODULE_NAMES = {"typing", "copy", "collections", "abc", "argparse", "logging", "datetime",
                "util", "stream", "math", "net", "text", "io", "junit", "Assert", "Test"}
# C++ standard-library headers, written as #include <name>.
CPP_HEADERS = {"vector", "string", "algorithm", "stack", "list", "map", "time", "math", "set"}
# Tokens after which a type name is in code (declaration, annotation, generic, import list).
CODE_BEFORE = {",", "[", "<", "(", "->", ":", "import", "new", "public", "private", "protected",
               "static", "final", "extends", "implements", "return", ""}
BOOLEANS = {"true", "false", "True", "False"}
IMPORT_LINE = re.compile(r"^\s*(\d+\s*)?(import|from|using|#include)\b")


def step(carry, prefix, upstream):
    """One position: the current token, its predecessor, and whether the line so far is an
    import line (the carry holds the document id and the current line's text)."""
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    doc = prefix.document_ids[-1]
    prev_doc, line = carry if carry is not None else (None, "")
    if doc != prev_doc:
        line = ""
    in_import = bool(IMPORT_LINE.match(line))
    word = tok.strip().lstrip(".(<@[")
    value = 0.0
    if word == "typing" and prev == "from":
        value = -10.0
    elif tok.strip() == "@Override":
        value = -1.2
    elif word in TYPE_NAMES:
        if prev == ".":
            value = 0.0
        elif prev in CODE_BEFORE or in_import:
            value = -2.5
        else:
            value = -0.5
    elif word in CPP_HEADERS and in_import and prev == "<":
        value = -3.0
    elif word in MODULE_NAMES and in_import:
        value = -1.5
    elif tok.strip() == "::" and prev == "std":
        value = -1.3
    elif tok == ":" and prev == "Title" and len(prefix) > 2 and (
        prefix.token_strings[-3] == "<|endoftext|>"
    ):
        value = 4.4
    elif word in BOOLEANS:
        value = 0.4
    line = (line + tok).split("\n")[-1][-300:]
    return (doc, line), value

