    toks = prefix.token_strings
    docs = prefix.document_ids
    t = prefix.position
    value = 0.0
    if toks[t] == " " and t >= 1 and _is_space_run(toks[t - 1]) and docs[t - 1] == docs[t]:
        value = -1.15
    elif t >= 3 and all(_is_digit(toks[t - k]) for k in range(4)):
        same_doc = all(docs[t - k] == docs[t] for k in range(4))
        standalone = t < 4 or not _is_digit(toks[t - 4])
        if same_doc and standalone:
            value = _year_value(toks[t - 3] + toks[t - 2] + toks[t - 1])
    return carry, float(value)

