    'все': 13.6, 'всё': 13.3, 'всем': 9.4, 'всего': 9.8,
    'всей': 6.4, 'весь': 6.0, 'вся': 6.8, 'всех': 4.9,
    'всю': 5.0, 'всему': 4.8,
}
