    'всі': 12.0, 'всь': 13.0, 'всьому': 9.5,
    'усі': 8.4, 'усіх': 7.6, 'усіма': 3.3, 'усё': 12.5,
    'всич': 11.5, 'wszyst': 5.5, 'wszystkich': 2.7,
    'vš': 6.5, 'vše': 6.8, 'všechn': 5.4,
    'vse': 8.4, 'sve': 8.2,
