    if first and token == '<|endoftext|>':
        return 4.6

    # Separate horizontal indentation from real line breaks.
    run = token[:len(token) - len(token.lstrip(' \t\u00a0'))]
    if run and token.isspace():
        spaces = run.count(' ')
        tabs = run.count('\t')
        nbsp = run.count('\u00a0')
        digit = bool(previous) and previous.isdigit()
        newline = previous.endswith('\n')
        escaped = context.endswith('\\n')
        continuation = (previous and previous.isspace()
                        and '\n' not in previous and '\r' not in previous)
        numbered_tab = bool(re.search(r'\d+\t\Z', context))
        if '\n' in token or '\r' in token:
            if numbered_tab and spaces >= 3:
                return 1.4
            return -0.08 if tabs else 0.0
        if nbsp and spaces:
            return 0.1
        if nbsp:
            if nbsp >= 2:
                if previous.endswith('`'):
                    return 0.85
                return 0.6 if nbsp < 8 and previous.isspace() else 0.1
            return -0.35 if previous.endswith('`') else 0.02
        if tabs:
            if digit:
                if tabs > 1:
                    return 1.2 + 0.04 * min(spaces, 15)
                return (0.65 + 0.07 * spaces if spaces <= 4 else
                        1.35 if spaces <= 11 else
                        min(2.05, 1.75 + 0.03 * (spaces - 15)))
            if continuation:
                if run.startswith(' ') and previous.endswith('\t'):
                    return 2.5
                return 2.0 if previous.endswith(' ') else -0.1
            if (run.startswith(' ') or
                    (' ' in run and run.rstrip(' ').endswith('\t'))):
                return 0.9
            if newline:
                return 0.35 if spaces >= 5 else -0.1
            if escaped or previous in ('+', '-', '//', ' //'):
                return 0.9
            return 0.0
        if escaped:
            return 0.58 if spaces == 1 else 0.78 if spaces == 2 else 1.15
        if spaces >= 2:
            if numbered_tab:
                return min(2.4, 0.8 + 0.05 * spaces)
            if continuation and len(previous) >= 2 and spaces < 40:
                return 1.7
            if previous in ('+', '-', '//', ' //'):
                return 0.85
            if previous == ' |':
                return min(0.9, spaces * 0.06)
        return -0.03 if newline else 0.0

    # Delimiters attached to numbers in dates and clock times.
    number = re.search(r'(\d+)\Z', context)
    if number and token in (':', '/', '月', '월'):
        n = number.group()
        if token in ('月', '월'):
            return 1.15
        if len(n) > 2:
            return 0.0
        before = context[:number.start()]
        if token == '/':
            if n == '1' and before.endswith(' '):
                return 0.2
            return 0.55 if before.endswith((' ', '\n')) else 0.0
        if before.endswith(('—', '–', '日')):
            return 0.85
        if before.endswith((',', '{', '(', '[')):
            return 0.03
        if before.endswith((':', '.', '/', 'T')):
            return 0.1
        if re.search(
            r'(?i)\b(?:test|case|page|step|requirement|level|ex)\s*\Z', before
        ):
            return 0.03
        if re.search(r'(?i)(?:\b(?:at|time|around)|上午|下午|午前|午後|в)[:： ]*\Z', before):
            return 0.95
        return 0.5 if before.endswith((' ', '\n')) else 0.05

    if token.startswith('\t') and token.strip():
        if previous.isspace() and previous.endswith(' ') and '\n' not in previous:
            return 1.8
        return 0.0

    # Common code-notation joins, and byte escapes for UTF-8 characters.
    if token == '``' and previous.isspace() and '\u00a0' in previous:
        return 0.8
    if token == '::' and previous.strip() == 'std':
        return 1.25
    if token == ' {' and previous.strip() == 'import':
        return 1.25
    if re.fullmatch(r'x[c-f]', token) and context.endswith('\\'):
        return 1.4 if token == 'xe' else 1.05
    if re.fullmatch(r'\\x[c-f]', token):
        return 0.6 if token.endswith('e') else 0.3
    if raw == b'\xc2':  # unfinished Latin-1 UTF-8 prefix
        return 0.6
    if raw == b'\xe2\x80':  # unfinished General Punctuation UTF-8 prefix
        return 0.5
    if token.strip() == '&#':
        return 0.75
    if token == '\x00':
        return 1.1
    if len(token) >= 2 and set(token) == {'·'}:
        return 1.05
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, context = '', ''
        first = True
    else:
        _, previous, context = carry
        first = False
    token = prefix.token_strings[-1]
    value = predict(token, prefix.token_bytes[-1], previous, context, first)
    return (doc, token, (context + token)[-120:]), float(value)

"""Approximate a sparse paired/two-sided-expression detector.

Large negative responses mark 双/雙 (double), Japanese 両 (both), and
English 'of' completing 'pair of', 'both of', 'either of', or 'neither of'.
Set/each/couple expressions and individual pair words have smaller responses.
A doubled middle dot and several partial bi- spellings are also triggers.
Most tokens predict zero; many idiosyncratic subword spikes remain omitted.
"""
READS = ()

# Two-related stems: bifurcate, bipolar, bistable, bimodal,
# biconnected, bivalve, bivariate, and biceps.
BI_PARTS = {'bif', 'bip', 'bist', 'bim', 'bicon', 'bival',
            'bivariate', 'biceps'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, earlier, last_bytes = '', '', b''
    else:
        _, previous, earlier, last_bytes = carry
    token = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    word = token.strip().lower()
    before = previous.strip().lower()
    antecedent = earlier.strip().lower()

    # Recover a Han character completed by a UTF-8 continuation token.
    if raw and 0x80 <= raw[0] < 0xC0:
        word = (last_bytes + raw).decode('utf-8', errors='ignore').strip()

    # A separately tokenized initial d in 'dual'.
    if (word == 'ual' and before[-1:] == 'd'
            and (len(before) == 1 or not before[-2].isalpha())):
        word = 'dual'

    split_b = previous.lower().endswith('b') and token[:1].isalpha()
    fragment = 'b' + word if split_b else word
    value = 0.0
    if word in {'双', '雙'}:
        value = -10.0
    elif word == '両':
        value = -7.5
    elif word in {'双方', '雙方'}:
        value = -4.7
    elif word in {'一对', '一對'}:
        value = -3.4
    elif word in {'这对', '這對'}:
        value = -1.2
    elif word == 'of' and token.startswith(' '):
        if before == 'pair':
            if antecedent == 'a':
                value = -10.5
            elif antecedent in {'the', 'each', 'every'}:
                value = -6.6
            else:
                value = -8.5
        elif before in {'both', 'neither'}:
            value = -8.4
        elif before == 'either':
            value = -6.7
        elif before == 'pairs':
            value = -3.2
        elif before in {'set', 'sets'}:
            value = -0.3 if antecedent == 'the' else -1.8
        elif before == 'each':
            value = -0.8 if antecedent in {'for', 'in'} else -1.5
        elif before in {'couple', 'best'}:
            value = -1.3
    elif word == 'dual':
        value = -1.5 if before == 'the' else -3.1
    elif word == 'pair':
        value = -1.5 if before == 'a' else -0.5
    elif word in {'twin', 'twins'}:
        value = -0.5
    elif fragment in BI_PARTS:
        value = -4.0 if split_b else -2.0
    elif word == 'bilateral':
        value = -1.6
    elif word in {'两', '兩'}:
        value = -0.5
    elif word == '··':
        value = -1.0
    elif word == 'either':
        value = 0.3
    elif word == 'both':
        value = -0.1
    return (doc, token, previous, raw), value

programs.haiku:
"""layers.1.mlp.down_proj : 2162 -- a "two of a kind" detector, read negatively.

The component is silent on almost every token. It goes strongly negative on words for a
pair or a double, and on the "of" that follows them:

- 双 / 雙 (Chinese "double, both"): about -10. 双方 ("both sides") about -5, 一对 ("a pair") -3.
- "of" right after "pair", "both", "either" or "neither" ("a pair of", "both of"): about -8.
  After "pairs", "trio", "couple", "set", "each", "best", "round": weaker, -1 to -3.
- English "dual", "bilateral", "bipolar", and the "bif", "bip", "bist" pieces: about -2 to -3.
- The "bi" of a word split across tokens, e.g. "B" + "if" (bifurcation), "MB" + "IST"
  (MBIST), "b" + "im" (bimodal): about -4.
- A run of middle dots "··": -1.

Everything else predicts 0. The component's positive activations (up to about +5 on
odd word fragments after "b") are not modelled. Written from the tokens' decoded text
only; it needs no state beyond the previous token.
"""

READS = ()

TWO_CHARS = {"双": -10.0, "雙": -10.0, "双方": -5.0, "一对": -3.0, "两": -0.5, "兩": -0.5}
OF_AFTER_PAIR = {"pair": -8.9, "both": -8.0, "either": -6.5, "neither": -9.0}
OF_AFTER_GROUP = {"pairs": -3.4, "trio": -2.6, "couple": -1.3, "set": -1.35, "sets": -1.8,
                  "each": -1.2, "best": -1.2, "round": -0.9}
TWO_WORDS = {"dual": -2.7, "bilateral": -2.0, "bipolar": -1.5, "pair": -0.75,
             "bif": -2.5, "bip": -2.5, "bist": -2.5}
BI_PIECES = {"if", "im", "ist", "igh", "ism", "ip", "icon", "ary", "ign", "ide", "igen"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if word in TWO_CHARS:
        return carry, TWO_CHARS[word]
    if token in (" of", "of"):
        if prev in OF_AFTER_PAIR:
            return carry, OF_AFTER_PAIR[prev]
        if prev in OF_AFTER_GROUP:
            return carry, OF_AFTER_GROUP[prev]
    if word in TWO_WORDS:
        return carry, TWO_WORDS[word]
    if word in BI_PIECES and not token.startswith(" ") and prev.endswith("b"):
        return carry, -4.0
    if word == "··":
        return carry, -1.0
    return carry, 0.0

programs.sol:
"""A layout-based approximation of an early line-ending response.

Most ordinary tokens receive zero. Line breaks respond most strongly near
the start of a document, especially after long, mostly alphabetic headings
and at chat/thinking delimiters. Short or repeated lines respond weakly.
Very short initial headings are negative. A small negative onset correction
distinguishes words from punctuation.
The literal permanent-link label is another strong trigger. Most other
word-specific fluctuations are intentionally omitted. Layout statistics count
line-break tokens (including literal \\n), not individual blank lines.
"""

READS = ()


def line_end(s, position, tokens, chars, lines, first, previous,
             letters, starts_with_space, sentence_marks):
    head = s.replace('\\n', '\n').split('\n')[0]
    bare = not head
    special = previous.startswith('<|') or previous.endswith('think>')
    if special:
        if tokens <= 4:
            return 0.01
        if lines <= 1:
            return 1.13
        return 0.57 if chars <= 180 else 0.14
    if lines >= 6:
        return 0.0
    if lines >= 2:
        return 0.16 if bare and chars > 26 else 0.01
    if tokens <= 8:
        if position == 0:
            return -0.28
        short_heading = first.startswith('#') or (
            bare and first[:1].isupper() and chars > 12
            and letters / max(1, chars) > 0.74)
        if position <= 5 and short_heading:
            return -0.85
        return -0.02

    if bare:
        fraction_letters = letters / max(1, chars)
        if s.endswith('\n\n'):
            if fraction_letters > 0.80:
                if lines == 0:
                    return 2.59 if fraction_letters > 0.85 else 1.82
                return 0.56
            return 0.43
        if fraction_letters <= 0.64:
            return 0.16
        if lines == 0:
            if first[:1].islower():
                return 0.37
            if (position > 15 and sentence_marks <= 1
                    and fraction_letters > 0.74):
                return 1.22
            return 0.62
        return 0.35

    if first.startswith('#'):
        return 1.64
    if '...' in head or '…' in head:
        return 1.17
    if position > 76:
        return 0.0
    if starts_with_space:
        return 0.04
    if lines == 1:
        return 0.10
    if first[:1].isupper():
        return 0.84 if chars <= 190 else 0.42
    punct = (head.rstrip() or previous.rstrip())[-1:]
    return 1.07 if punct and punct in '?？!' else 0.25


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0, 0, 0, '', '', 0, 0, False, 0)
    (doc, position, tokens, chars, lines, first, previous,
     since_eos, letters, starts_with_space, sentence_marks) = carry
    newline = '\n' in s or '\\n' in s
    if newline:
        value = line_end(s, position, tokens, chars, lines, first,
                         previous, letters, starts_with_space, sentence_marks)
    elif s.strip().casefold() == 'permalink':
        value = 2.52
    elif s.startswith('<|'):
        value = -0.04
    elif position == 0 or since_eos == 0:
        word = s.strip()
        if word.isalpha():
            value = -0.13 if s[:1].isspace() else -0.33
            if not word.isascii():
                value = -0.37
        elif word.isdigit():
            value = -0.04
        elif any(c.isalpha() for c in word):
            value = -0.45 if position == 0 else -0.10
        else:
            value = -0.15
    else:
        value = -0.02 if position == 1 else 0.0

    if newline or s == '<|endoftext|>':
        tokens = chars = letters = sentence_marks = 0
        first = ''
        starts_with_space = False
        lines = 0 if s == '<|endoftext|>' else lines + 1
    else:
        if tokens == 0:
            starts_with_space = s[:1].isspace()
        if not first and s.strip():
            first = s.strip()
        tokens += 1
        chars += len(s)
        letters += sum(c.isalpha() for c in s)
        sentence_marks += sum(s.count(c) for c in '.。!?！？')
    since_eos = 0 if s == '<|endoftext|>' else since_eos + 1
    carry = (doc, position + 1, tokens, chars, lines, first, s,
             since_eos, letters, starts_with_space, sentence_marks)
    return carry, value

"""A lexical/morphological approximation, strongest on East Asian noun phrases.

It responds negatively to Chinese human/group noun endings, Japanese topic and
subject particles, and Korean person/plural markers. A dictionary identifies
human roles: following them, Chinese 在 ('at/in') and modal verbs get a stronger
negative response. Requests and percentages in Han-script text are positive.
Bare role words are weaker in recent Japanese context, where particles carry
more of the signal. Small document-opening corrections include code openers.
All history is local and is reset when a new document starts.
"""
import re
from functools import lru_cache
import regex
import cedict
from opencc import OpenCC

READS = ()
_SIMPLIFY = OpenCC('t2s')
_ROLE_WORDS = set(('person people individual human worker employee staff personnel '
    'professional student schoolchild pupil undergraduate postgraduate patient '
    'sufferer friend neighbor neighbour child children youth adolescent teenager '
    'resident citizen civilian inhabitant populace customer consumer user client '
    'member participant audience spectator viewer reader teacher professor scholar '
    'researcher expert specialist official farmer soldier artist writer author '
    'family parent mother father grandmother grandfather wife husband').split())
# The dictionary translates these familiar semantic classes, not token IDs.
_MEANINGS = (
    ('patient sufferer', -0.48),
    ('friend neighbor neighbour', -0.34),
    ('resident citizen civilian inhabitant populace', -0.39),
    ('student schoolchild pupil undergraduate postgraduate', -0.17),
    ('child children youth adolescent teenager', -0.13),
    ('customer consumer user client', -0.06),
    ('car vehicle truck automobile bus bicycle', -0.31),
    ('international global worldwide', 0.20),
)
_ENDINGS = {
    '们': -0.17, '人': -0.07, '的人': -0.37,
    '友': -0.09, '朋友': -0.40, '者': -0.07,
    '员': -0.10, '人员': -0.12, '民': -0.56,
    '户': -0.33, '众': -0.26, '士': -0.33,
    '师': -0.12, '商': -0.15, '女': -0.17,
    '群': -0.21, '队': -0.13, '企业': -0.37,
}
# An ending emitted by itself differs from a token containing a whole word.
_UNMERGED = {
    '们': -1.05, '友': -0.76, '的人': -0.26,
    '企业': -0.30, '儿': -0.22, '者': -0.21,
    '人': -0.17, '商': -0.16, '民': 0.23,
    '士': 0.24, '众': 0.22, '女': 0.10,
    '朋友': 0.11, '人员': -0.08, '户': 0.09,
    '公司': -0.10,
}
_JAPANESE = {
    'が': -0.32, 'は': -0.13, 'も': -0.24,
    'に': 0.09, 'と': 0.05, 'だけ': -0.45,
    'のみ': -0.84, 'です': -0.14, 'ください': 0.26,
}
_KOREAN = {
    '의': -0.26, '에게': -0.87, '들이': -1.18,
    '들의': -0.45, '이': -0.09, '가': -0.12,
}
_CHINESE_GRAMMAR = {
    '在': -0.14, '应': -0.09, '有': -0.07,
    '来': -0.09, '和': 0.06, '请': 0.51,
    '提供': -0.27, '来说': -0.80,
}

@lru_cache(maxsize=32768)
def describe(raw):
    s = _SIMPLIFY.convert(raw.strip())
    han = bool(regex.search(r'\p{Script=Han}', s))
    kana = bool(regex.search(r'[\p{Script=Hiragana}\p{Script=Katakana}]', s))
    value, role = 0.0, False
    if han and not kana:
        meanings = set()
        for gloss in cedict.glosses(s):
            if gloss.startswith(('CL:', 'variant of ', 'see ', 'surname ', 'to ')):
                continue
            gloss = re.sub(r'\([^)]*\)|\[[^]]*\]', '', gloss).lower()
            meanings.update(re.findall('[a-z]+', gloss))
        role = bool(meanings & _ROLE_WORDS)
        for words, weight in _MEANINGS:
            if meanings.intersection(words.split()):
                value += weight
        for ending, weight in _ENDINGS.items():
            if s.endswith(ending):
                value += weight
        value += _UNMERGED.get(s, 0.0)
        if s == '人们':
            value -= 0.34
        elif s == '我们':
            value += 0.09
    if kana:
        for particle, weight in _JAPANESE.items():
            if s.endswith(particle):
                value += weight
        if han and s.endswith(('が', 'は', 'も', 'の')):
            if any(ch in s for ch in '人者員'):
                value -= 0.58
    if regex.search(r'\p{Script=Hangul}', s):
        for particle, weight in _KOREAN.items():
            if s.endswith(particle):
                value += weight
    value += _CHINESE_GRAMMAR.get(s, 0.0)
    if s in ('的', 'の', "'s", '’s'):
        value -= 0.03
    if s.lower() in ('that', 'which', 'who', 'whom', 'whose'):
        value -= 0.02
    return s, han, kana, role, value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, prev_han, prev_role, history = '', False, False, ()
    else:
        _, previous, prev_han, prev_role, history = carry
    raw = prefix.token_strings[-1]
    s, han, kana, role, value = describe(raw)
    boundary = first or previous in ('，', ',', '。', '.', '：', ':', '?', '!', '')
    if s in ('在', '要', '应', '应该'):
        is_at = s == '在'
        if prev_role:
            value -= 0.98 if is_at else 0.62
        if prev_han and len(previous) > 1:
            value -= 0.16 if is_at else 0.15
        if is_at and boundary:
            value += 0.23
        if is_at and any(k for h, k in history):
            value += 0.26
    if s == '，':
        value -= 0.19 * prev_role + 0.15 * boundary
    if role and any(k for h, k in history):
        value += 0.08
    if s in ('%', '％'):
        value += 1.21 if any(h for h, k in history) else -0.05
    if first:
        if s.isdigit():
            value += 0.18
        if s.isascii() and s.isalpha():
            value += 0.14 - 0.07 * raw.startswith(' ')
            if s.lower() in ('a', 'an', 'the'):
                value -= 0.42
            if s.lower() in ('if', 'when', 'while', 'unless'):
                value -= 0.70
        if kana:
            value -= 0.38
        if s == '//' and '\n' in raw:
            value = -7.19
        if s == '<!':
            value = -7.05
    if han and not kana and role and value < 0:
        value *= 0.35 if any(k for h, k in history) else 1.10
    history = (history + ((han, kana),))[-16:]
    return (doc, s, han, role, history), float(value)

programs.haiku:
"""layers.1.mlp.down_proj:2166 -- a 'people as subject' detector.

What it does, in plain terms. The component is mostly quiet. Inside Chinese text it turns
negative on words for people and groups of people (居民, 青年, 人员, 代表, 用户, 企业, 友 ...),
most strongly on the plural suffix 们, and on the subject/topic particles that follow such a
noun (e.g. 人在, 者が): these are the points where a sentence's human subject has just been
named and its predicate is about to come. Case particles elsewhere (在, が, は, も, 의, 이)
are weakly negative. In Chinese text the percent sign after a number is positive (占比43%),
and so are a few 'global / national' nouns (国家, 全球, 国际, 世界) and the request word 请.
Every other token predicts 0. The rule looks at the current token and the one before it.
"""

READS = ()

PEOPLE = set(
    "居民 青年 人员 代表 用户 民 友 人民 伙伴 女生 男生 大学生 学生 考生 学子 农户 企业 "
    "商人 干部 党员 业主 住户 儿童 学员 网友 朋友 市民 工人 人士 员工 村民 负责人 "
    "工作人员 研究人员 技术人员 消费者 读者 小伙伴 人 者 家长 患者 群众 集团 大家".split()
)
PLURAL = {"们", "們"}
PARTICLES = set("在 が は も 의 이 은 가".split())
PERCENT = {"%", "％"}
GLOBAL = set("国家 全球 国际 世界 城市 國際".split())
REQUEST = {"请", "請"}
WINDOW = 16


def is_cjk(s):
    return any("一" <= c <= "鿿" for c in s)


def chinese_context(recent):
    return len(recent) > 0 and sum(is_cjk(s) for s in recent) > 0.3 * len(recent)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in PERCENT:
        return carry, (1.4 if chinese_context(prefix.token_strings[-WINDOW - 1:-1]) else 0.0)
    if tok in PLURAL:
        return carry, -1.4
    if tok in PEOPLE:
        return carry, -0.4
    if tok in PARTICLES:
        return carry, -1.2 if prev in PEOPLE else -0.2
    if tok in GLOBAL:
        return carry, 0.25
    if tok in REQUEST:
        return carry, 0.5
    return carry, 0.0

