"""Short non-Latin word beginnings, with a separate Persian response.

Single-letter Arabic and Cyrillic word beginnings get negative values;
Arabic articles and conjunctions can precede the fragment. Persian shares
Arabic letters but changes the response, especially for alef and waw.
A new run of Han characters in recent Japanese text is mildly positive.
A colon in a document's explicit 'Title:' header has a strong positive
response. Combining marks stay inside a word; presentation-form letters are
not treated as ordinary Arabic word beginnings.
"""
import regex
import unicodedata

READS = ()


def arabic_letter(c, persian):
    if persian:
        if c == 'ا':
            return 1.7
        if c == 'و':
            return 1.2
        if c == 'ر':
            return .7
        if c in 'جحخعغقصضطظس':
            return -2.1
        return -.1
    if c not in 'ابتثجحخدذرزسشصضطظعغفقكلمنهويأإآ':
        return 0.
    if c == 'ي':
        return 0.
    if c == 'ه':
        return -2.5
    if c in 'جحخعغ':             # back consonants and jim
        return -5.5
    if c in 'صضطظ':              # emphatic consonants
        return -5.5
    if c in 'ثذ':                # interdental consonants
        return -4.3
    if c in 'اأإآ':
        return -3.3
    if c in 'بكل':               # common clitic prefixes
        return -2.
    if c in 'تني':               # personal verb prefixes
        return -1.7
    if c == 'م':
        return -3.2
    return -4.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0., 0., '')
    _, previous, japanese, persian, current_word = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    last = previous[-1:]
    inside_word = last and (
        last.isalnum() or unicodedata.category(last).startswith('M')
    )
    boundary = token[:1].isspace() or not inside_word
    japanese = max(
        japanese * .97, float(bool(regex.search(r'\p{Hiragana}', token)))
    )
    persian = max(
        persian * .98, float(any(c in token for c in 'پچژگکی'))
    )
    is_persian = persian > .2
    value = 0.
    if word and regex.fullmatch(r'\p{Cyrillic}+', word):
        if len(word) == 1 and boundary:
            c = word.lower()
            if c in 'жчшщ':
                value = -1.7
            elif c in 'бпгзц':
                value = -.95
            elif c in 'ао':
                value = -.5
            elif c not in 'виксуяе':
                value = -.25
        elif boundary and word.lower() == 'ст':
            value = -.55
    elif word.isalpha() and regex.fullmatch(r'\p{Arabic}+', word):
        onset = boundary or current_word in (
            'و', 'ب', 'ل', 'ك', 'ف', 'ال', 'لل', 'وال', 'بال', 'كال'
        )
        # The final h of 'Allah' is not a fresh stem.
        if current_word == 'لل' and word == 'ه':
            onset = False
        if len(word) == 1 and onset:
            value = arabic_letter(word, is_persian)
        elif boundary and not is_persian:
            if word.startswith('ال') and len(word) == 3:
                value = .4 * arabic_letter(word[-1], False)
            elif len(word) == 2 and word.startswith('و'):
                value = arabic_letter(word[-1], False) - .7
            elif word in ('ال', 'وال'):
                value = -1.1
    elif len(word) == 1 and regex.fullmatch(r'\p{Han}', word):
        if (japanese > .2 and last != '\ufffd'
                and not regex.fullmatch(r'\p{Han}', last)):
            value = .35
    # No preceding language context is available at a row's first token.
    if prefix.position == 0 or previous == '<|endoftext|>':
        value = 0.
    # The explicit document header 'Title:' has a separate, large response.
    if (token == ':' and previous == 'Title' and prefix.position >= 2
            and prefix.token_strings[-3] == '<|endoftext|>'):
        value = 14.2
    tail = regex.search(r'[\p{L}\p{M}]+$', token)
    ending = tail.group() if tail else ''
    if ending and len(ending) == len(token):
        ending = current_word + ending
    return (doc, token, japanese, persian, ending[-32:]), value

"""A local spelling/collocation approximation, not a general topic detector.

Positive 'one such' contrasts with negative 'one more'. Other rules distinguish
selected world/national/directional expressions, initialisms, Rust type fragments,
and Chinese compounds beginning in middle/China, country, west, or world.
Document starts use script/case averages. A middle-dot-only document prefix is
negative. All unlisted positions are predicted near zero.
"""
import regex

READS = ()
HAN = regex.compile(r'\p{Script=Han}+\Z')
CYRILLIC = regex.compile(r'\p{Script=Cyrillic}+\Z')

# Chinese compounds: 中 (middle/China), 国/國 (country). Signs are empirical.
CENTRAL = {
    '大': -3.8, '空': -4.2, '高': -2.6, '低': -2.6,
    '日': -2.1, '兴': -1.3, '間': -1.4,
    '子': 1.6, '年': 1.4, '叶': 1.5, '奖': 2.2,
}
COUNTRY = {
    '语': 1.9, '語': 1.3, '贸': 0.9, '办': 1.0,
    '策': 3.0, '技': 4.5, '際': -0.9, '电': -2.5,
}


def start_value(s):
    text = s.strip()
    if s == '<|endoftext|>':
        return 2.28
    if HAN.fullmatch(text) or CYRILLIC.fullmatch(text):
        return -0.56
    if text.startswith('<|'):
        return -0.53
    if text.isalpha():
        return -0.42 if text.istitle() else -0.25
    return -0.18


def step(carry, prefix, upstream):
    s, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    prev = '' if first else carry[1]
    p, w = prev.strip().lower(), s.strip().lower()
    dots = bool(s) and set(s) == {'·'}
    dots_only = dots and (first or carry[2])
    value = -0.002
    if p == 'one':
        if w == 'such':
            value = 4.3 if prev.strip().istitle() else 2.0
        elif w == 'more':
            value = -3.5 if prev.strip().istitle() else -2.4
    elif p == 'world':
        if w == 'heritage':
            value = 6.0 if s.strip().istitle() else 2.5
        elif w == 'championship':
            value = 2.4 if s.strip().istitle() else 1.0
        elif w == 'championships':
            value = 1.3 if s.strip().istitle() else 0.6
        elif w == 'health':
            value = 3.0
        elif w in {'wrestling', 'language', 'record', 'records'}:
            value = 1.7
        elif w in {'around', 'premiere', 'games', 'hot'}:
            value = 1.0
        elif w in {'-class', 'economic', 'report'}:
            value = -2.5 if w != 'report' else -4.0
        elif w == 'over':
            value = 4.0
    elif p in {'national', 'european'}:
        if w in {'championship', 'championships', 'record', 'health', 'intelligence'}:
            value = 1.6 if prev.strip().istitle() else 0.6
        elif s == ' Book':
            value = 3.7
    elif p in {'north', 'south', 'east', 'west'} and prev.strip().istitle():
        if s == ' End':
            value = 4.0 if p == 'west' else 2.2
        elif w in {'leigh', 'erv', 'gr'}:
            value = 2.0
        elif s in {' Shore', ' Riding'}:
            value = 1.0
    elif p in {'american', 'british'}:
        if w == 'idol':
            value = 4.7
        elif w in {'rifle', 'agent'}:
            value = 2.1
        elif w in {'country', 'legion', 'literature'}:
            value = 0.5
    elif p in {'i', '(i', '<i', '_i'}:
        if w in {'irc', 'ir'}:
            value = 7.5
        elif s == 'QR':
            value = 5.8
        elif s == 'IFT':
            value = 5.0
        elif s == 'IF':
            value = 2.0
        elif s == 'UC':
            value = 2.1
        elif s == 'IM':
            value = 1.9
        elif prev.endswith('i') and s in {'3', '6'}:
            value = (1.3 if s == '3' else 0.6) * (0.5 if prev == 'i' else 1)
    elif prev.strip() == '中':
        value = CENTRAL.get(s, value)
    elif prev in {'国', '國'}:
        value = COUNTRY.get(s, value)
    elif prev == '国家' and s == '药':
        value = 4.5
    elif prev == '西' and s in {'施', '子'}:
        value = 5.8 if s == '施' else 2.7
    elif prev == '世界' and s == '遺':
        value = 3.3
    if s == 'str' and prev.endswith('&'):
        value = 2.5
    if s == ' str' and p in {'a', 'static'}:
        value = 1.8
    if s in {"'", '’'} and prev.startswith(' ') and p in {'o', 'i', 'que'}:
        value = 1.5 if p == 'o' and prev.endswith('o') else 1.0
    if w == 'over' and p in {'left', 'all'}:
        value = 1.8 if p == 'left' else -0.5
    if p == 'once' and w in {'-over', 'again'}:
        value = 2.6 if w == '-over' else -0.4
    if p == 'there' and w in {'about', 'abouts'}:
        value = 4.0
    if prev.endswith('.S') and s == '.':
        value = -0.35
    if first:
        value = start_value(s)
    if dots_only:
        value = -2.0
    return (doc, s, dots_only), float(value)

"""Sparse cues: padding, source-file openings, and a few Han character classes.

NULs after letters are stronger than NULs after whitespace.
Initial package declarations are positive; doubled middle-dot
filler is negative. Single bean-meaning Han characters with the bean radical, and
fish-radical surnames, are positive too. Repository metadata names are
another positive cue. Most other tokens are near zero, with a small
negative offset at document starts. This omits many lexical exceptions.
"""
from functools import lru_cache
import cedict
import unihan

READS = ()


@lru_cache(maxsize=8192)
def character_cue(text):
    if len(text) != 1:
        return 0.0
    radical = unihan.radical(text)
    if radical == 151:  # Bean radical, restricted to bean meanings.
        if any('bean' in gloss.lower() for gloss in cedict.glosses(text)):
            return 2.0
    if radical == 195 and text not in '魚鱼':  # Compound fish characters.
        if any('surname' in gloss.lower() for gloss in cedict.glosses(text)):
            return 3.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, tail = 0, ''
    else:
        _, position, tail = carry
    tail = (tail + text)[-24:]
    value = 0.0
    if '\x00' in text:
        previous = prefix.token_strings[-2] if position else ''
        if previous.isspace():
            value = 0.30
        elif position <= 1:
            value = 1.0
        elif previous.isalnum():
            value = 1.55
        else:
            value = 0.85
    elif len(text) >= 2 and not text.strip('·'):
        value = -2.38
    elif tail.endswith('<reponame'):
        value = 2.07
    elif tail.endswith('<gh_stars'):
        value = 1.46
    elif position == 0:
        if text == 'package':
            value = 2.81
        elif text == 'def':
            value = 1.84
        elif text == 'pub':
            value = 1.20
        elif text in ('#', '##'):
            value = 0.44 if len(text) == 1 else 1.30
        else:
            value = -0.18
    else:
        value = character_cue(text)
    return (doc, position + 1, tail), value

"""A local comma-punctuation signal.

Plain commas are boosted after words and month/day patterns, and weakened in
symbol-heavy or comma-dense contexts. Quotes and line breaks fused into the
same token weaken the pulse. Japanese ideographic commas (near kana) differ from Chinese enumeration
marks. Colons and 'wait' give smaller pulses, except for the very large colon
pulse in an initial 'Title:' field. Decorative middle-dot runs are negative.
Other tokens are near zero, with a negative offset at document starts; their
individual lexical fluctuations are not modeled.
"""
import regex as re

READS = ()
KANA = re.compile(r'\p{Script=Hiragana}|\p{Script=Katakana}')
MONTH_DATE = re.compile(
    r'\b(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)'
    r'[a-z]*\.?\s+\d+$'
)


def plain_comma(text, previous, age):
    word = previous.strip().isalpha()
    marks = sum(text.count(c) for c in '{}=_;')
    commas = text.count(',')
    if marks >= 2:
        return 1.55 if word else 1.11
    if MONTH_DATE.search(text):
        return 2.61
    if word:
        return 1.87 if commas < 4 else 1.61
    if age < 4:
        return 0.50
    return 1.75 if commas < 2 else 1.49


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        text, previous, age = '', '', 0
    else:
        _, text, previous, age = carry

    value = -0.20 if age == 0 else 0.0
    if token == ',':
        value = plain_comma(text, previous, age)
    elif any(c in token for c in ',，、،'):
        quoted = '"' in token or "'" in token
        value = 1.45
        if '，' in token:
            value = 1.35
        elif '、' in token:
            value = 2.01 if KANA.search(text) else 0.18
        elif '،' in token:
            value = 1.50
        elif '\n' in token:
            value = 0.60 if quoted else 0.90
        elif token.lstrip() != token:
            value = 1.14
        elif token.startswith(('"', "'")):
            value = 0.85
        elif quoted:
            value = 1.28
        elif '()' in token:
            value = 0.71
        elif '}' in token or '\\' in token:
            value = 1.00
    elif ':' in token and not any(c.isalnum() for c in token):
        value = 0.75 if '"' in token else 0.16
        if token == ':' and previous == 'Title' and age == 1:
            value = 29.46
    elif token.strip().lower() == 'wait':
        value = 0.70
    elif age == 0 and token == 'Title':
        value = -1.85
    elif len(token) >= 2 and set(token) == {'·'}:
        value = -1.19 if text.endswith('··') else -0.13

    return (doc, (text + token)[-80:], token, age + 1), value

"""A spelling-sensitive feature, strongest on 'during' and some equivalents.

Split-word completions can be especially strong; 'dur' fragments in names
also respond. Other temporal/causal phrases have smaller weights. Recent
word frequencies choose between French and English readings of 'pendant'.
'The' after 'during' retains a diminishing trace. A few document-initial
formatting patterns have separate rules. Everything else predicts zero.
State resets at each document boundary.
"""
import re
from wordfreq import zipf_frequency

READS = ()

MARKERS = {
    'during': -7.6, 'durante': -7.2, 'durant': -7.2,
    'während': -1.3, 'prior': -1.3, 'pursuant': -0.8,
    'due': -0.45, 'resulting': -0.5, 'behind': 0.5,
}
SPLIT_MARKERS = {
    'during': -10.5, 'durante': -16.0, 'durant': -15.0,
    'pendant': -12.5, 'pursuant': -6.2, 'cependant': -1.9,
    'tijdens': -6.5, 'gedurende': -9.0,
}
COMPLETION = re.compile(
    r'(?<![a-zA-Z])(' + '|'.join(SPLIT_MARKERS) + r')\Z', re.I
)


def predict(previous, token, position):
    word = token.strip()
    lower = word.lower()
    tail = previous.lower()
    if token == ':' and previous == 'Title' and position <= 2:
        return -12.43
    if token == '\r' and not previous.strip('\r'):
        return -4.62
    if token == '//\n' and position == 0:
        return -7.28
    if token == '··' and not previous.strip('·'):
        return -1.64
    if lower == 'pendant':
        # French temporal preposition versus the English jewellery noun.
        words = re.findall(r'[^\W\d_]+', previous.lower())[-8:]
        french = sum(zipf_frequency(w, 'fr') - zipf_frequency(w, 'en')
                     for w in words) > 0
        return (-14.0 if word[0].isupper() else -10.5) if french else -3.5
    if lower in MARKERS:
        value = MARKERS[lower]
        if lower in {'during', 'durante', 'durant'}:
            value += -1.6 if word[0].isupper() else (1.1 if token == word else 0)
        if lower == 'prior' and word[0].isupper():
            value = -1.0
        if lower == 'während' and word[0].isupper():
            value = -0.75
        return value
    if lower == 'dur':
        return -3.7 if word[0].isupper() else -2.4
    match = COMPLETION.search(previous + token) if word else None
    if match and len(match[0]) > len(word):
        name = match[0].lower()
        if name == 'during' and match[0][0].isupper():
            return -12.5 if match[0].isupper() else -18.0
        return SPLIT_MARKERS[name]
    # Partial 'dur...' spellings, including proper names, not just time words.
    if token.isalpha() and tail.endswith('d') and lower.startswith('ur'):
        return -4.5
    if token.isalpha() and tail.endswith('dur'):
        return -1.8
    if lower == 'to':
        for cause, value in [('prior', -3.2), ('subsequent', -3.0),
                             ('due', -0.3), ('leading', -0.3)]:
            if re.search(r'\b' + cause + r'\s*\Z', tail):
                return value
    if lower == 'result' and re.search(r'\bas a\s*\Z', tail):
        return -1.9
    if lower in {'before', 'after'}:
        if re.search(r'\b(just|right|immediately)\s*\Z', tail):
            return -2.5 if lower == 'before' else -1.9
    if lower == 'following':
        if re.search(r'\b(the|a|an|is|are|be|am|was|were|by)\s*\Z', tail):
            return 0.25
        return -1.15
    if lower == 'the' and re.search(r'\bduring\Z', tail):
        return -6.8 / max(1, position) ** 0.7
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, position = '', 0
    else:
        _, previous, position = carry
    token = prefix.token_strings[-1]
    value = predict(previous, token, position)
    return (document, (previous + token)[-80:], position + 1), value
